/**
 * Binary Queue Codec (BQC) — Secure v3
 *
 * Two operating modes:
 *
 *   Legacy mode  (key = '')
 *     4-bit S-box, no IV, no HMAC. Fully backward-compatible.
 *
 *   Secure mode  (key != '')  — wire format v3 (magic "BS")
 *     8-bit S-box derived via HKDF + Fisher-Yates shuffle.
 *     S-box nonlinearity is verified (NL >= 80) using Fast Walsh-Hadamard
 *     Transform; weak S-boxes are regenerated (up to 16 attempts).
 *     Random 16-byte IV ensures identical plaintexts produce distinct ciphertexts.
 *     HMAC-SHA256 (full 32 bytes) authenticates the ciphertext.
 *     Per-round bit-rotation keys expand bit-permutation variants from 8 to 8^5.
 *     Three independent HKDF-derived table keystreamss (tableKey / tableKeyB /
 *     tableKeyC) ensure steps 2b, 4a/4b, and 5b are cryptographically decoupled.
 *     LFSR rotation sequence (period 7) replaces fixed rotL/rotR in steps 3/6,
 *     extending the differential cascade orbit to lcm(7, n) ≥ 56 bytes.
 *     n×n grid ShiftRows (step 3) redistributes bytes across column boundaries,
 *     analogous to AES ShiftRows, breaking per-column independence.
 *
 *   Ciphertext wire format (secure mode v3, before base64url):
 *     magic[2] | IV[16] | attempt[1] | octalLen[4] | octal[N] | HMAC[32]
 *
 *   Backward compatibility:
 *     V1 (magic "BQ", HMAC-128) and V2 (magic "BR", HMAC-256) ciphertexts
 *     are still fully decryptable.
 *
 *   Key space (source code fully public):
 *     S-box       : derived from HKDF output; effective entropy bounded by key length
 *     bit-rotation: 8^5 = 32 768 per-round combinations (was 8 in V2)
 *     params      : 7 × 6 × 4 × 4 = 672 combinations (derived deterministically from key)
 *     Security    : effective key strength equals min(input key entropy, 256 bits)
 *
 * Encryption pipeline:
 *   plaintext
 *     → diffuse  (key S-box + prime S-box + XOR cascade + prime Z/256Z add
 *                  + bit permutation + XOR cascade, key-derived rounds)
 *     → hex      (prepend 0xFF sentinel to preserve leading bytes)
 *     → binary
 *     → run-length queue encode  (key-derived runMax)
 *     → prefix compression       (SENTINEL='5', survives octal roundtrip)
 *     → octal string
 *     → base64url
 *
 * Ciphertext expansion:
 *   The encoding pipeline (hex → binary → RLE → octal → base64) causes
 *   significant ciphertext expansion.  Worst-case ratio (alternating bits,
 *   runMax=1) is approximately 8–10× the plaintext length.  Typical ratio
 *   for random-looking diffused data is 3–5×.  Applications should account
 *   for this when sizing storage or transport buffers.
 *
 * Pure PHP — requires PHP >= 7.1.2 (hash_hkdf). No external extensions.
 *
 * Performance note:
 *   The decimal ↔ octal conversion uses string-based big-integer arithmetic
 *   with O(n²) complexity.  For plaintexts exceeding ~10 KB the encoding
 *   step may become a bottleneck.  If GMP or bcmath is available, consider
 *   replacing bigMulSmall / bigDivModSmall with native arbitrary-precision
 *   functions for significantly better throughput.
 * 
 * @phpstan-type LegacyParams array{
 *     rotL: int,
 *     rotR: int,
 *     rounds: int,
 *     runMax: int,
 *     sbox: array<int, int>,
 *     sboxInv: array<int, int>,
 *     secure: false,
 * }
 * @phpstan-type SecureParams array{
 *     rotL: int,
 *     rotR: int,
 *     rounds: int,
 *     runMax: int,
 *     sbox: array<int, int>,
 *     sboxInv: array<int, int>,
 *     hmacKey: string,
 *     tableKey: array<int, int>,
 *     bitRotKey: int,
 *     bitRotKeys: array<int, int>,
 *     tableKeyB: array<int, int>,
 *     tableKeyC: array<int, int>,
 *     gridN: int,
 *     secure: true,
 *     attempt: int,
 *     vecTable: array<int, int>|null,
 *     primeShiftKey: array<int, int>|null,
 * }
 * @phpstan-type PipelineParams LegacyParams|SecureParams
 */
final class BinaryQueueCodec
{
	// ─── Wire format constants ────────────────────────────────────────

	/** Two-byte magic that identifies secure-mode ciphertext (v1, HMAC-128). */
	private const SECURE_MAGIC = "\x42\x51";  // ASCII 'BQ'

	/**
	 * Two-byte magic that identifies secure-mode v2 ciphertext.
	 *
	 * V2 differences from V1:
	 *   - Full 32-byte HMAC-SHA256 (not truncated to 16 bytes)
	 *   - Key-derived table masking (tableKey XORed into PRIME_TABLE /
	 *     COMPOSITE_GAP_TABLE lookups — makes all fixed constants key-dependent)
	 *   - Key-derived bit rotation (bitRotKey pre-rotates each byte before
	 *     BIT_PERM, making the effective bit permutation key-specific)
	 *
	 * Wire format (before base64url):
	 *   magic[2] | IV[16] | attempt[1] | octalLen[4] | octal[N] | HMAC[32]
	 *
	 * V1 ciphertexts (magic = BQ) are still fully decryptable.
	 */
	private const SECURE_MAGIC_V2 = "\x42\x52"; // ASCII 'BR'

	/**
	 * Two-byte magic that identifies secure-mode v3 ciphertext.
	 *
	 * V3 differences from V2:
	 *   - Per-round bit-rotation keys (bitRotKeys[0..4]), one per round.
	 *     Expands effective bit-permutation variants from 8 (2³) to 8⁵ = 32 768.
	 *   - Independent tableKeyB (32 bytes) for step 5b masking, derived from a
	 *     separate HKDF region so it is cryptographically decorrelated from the
	 *     tableKey used in steps 2b/4a/4b.
	 *   - Independent tableKeyC (32 bytes) for step 2b masking, so steps 2b and
	 *     4a/4b no longer share the same tableKey index.
	 *
	 * Wire format (before base64url): identical to V2.
	 *   magic[2] | IV[16] | attempt[1] | octalLen[4] | octal[N] | HMAC[32]
	 *
	 * HKDF layout (659 bytes total, was 579):
	 *   bytes   0–509  Fisher-Yates shuffle (unchanged)
	 *   bytes 510–513  rotL, rotR, rounds, runMax (unchanged)
	 *   bytes 514–545  HMAC-SHA256 subkey (unchanged)
	 *   bytes 546–577  tableKey   — steps 4a / 4b masking (unchanged)
	 *   bytes 578–582  bitRotKeys[0..4] — per-round bit-rotation (& 0x07 each)
	 *   bytes 583–614  tableKeyB  — step 5b masking (independent from tableKey)
	 *   bytes 615–646  tableKeyC  — step 2b masking (independent from tableKey)
	 *
	 * V1/V2 ciphertexts remain fully decryptable.
	 */
	private const SECURE_MAGIC_V3 = "\x42\x53"; // ASCII 'BS'

	/**
	 * Two-byte magic that identifies secure-mode v4 ciphertext.
	 *
	 * V4 differences from V3:
	 *   - AES S-box (NL=112) composed with the HKDF-derived S-box, replacing the
	 *     plain Fisher-Yates S-box used in V3.  Effective substitution chain:
	 *     PRIME_SBOX ∘ AES_SBOX ∘ hkdf_sbox — maximum algebraic diversity.
	 *   - Compact nibble-packed encoding: RLE digit output is packed at 2 digits
	 *     per byte (4-bit nibbles) using bitwise operations, replacing the O(n²)
	 *     big-integer decimal→octal conversion with O(n) bit manipulation.
	 *     Reduces encoding overhead from 3–10× to approximately 4/3× plaintext.
	 *   - (P1) Nonlinear XOR cascade: step 3/6 feed bytes[i±1] through the key
	 *     S-box before rotation+XOR.  A single-bit change fans out to ~4 bits
	 *     via the S-box before entering the cascade, doubling per-step diffusion.
	 *   - (P3) AES-style MixColumns: after step 5 (bit permutation), each 4-byte
	 *     group is multiplied by the AES MDS matrix [2,3,1,1] in GF(2^8).
	 *     Branch number = 5 guarantees any 1-byte input change propagates to all
	 *     4 output bytes.  Inverse uses the [14,11,13,9] matrix.
	 *   - (P4) Precomputed 256-entry LUTs for permuteByte / unPermuteByte,
	 *     replacing the O(8) per-bit loop with O(1) table lookup.
	 *   - (P6) S-box whitening between the vecTable and primeShift post-layers,
	 *     inserting a nonlinear boundary that prevents an attacker from combining
	 *     two linear transforms into a single affine relation.
	 *   - Prime-gap swap (step 3b): after cascade + ShiftRows, swaps bytes at
	 *     positions separated by prime gaps (PRIME_GAPS_256), XOR-masked with
	 *     HKDF-derived swapKey.  Each swap is followed by nonlinear S-box XOR
	 *     feedback.  Stabilises worst-case avalanche at low round counts
	 *     (min 0.09 → 0.34 at 1 round) by connecting cascade-distant byte pairs.
	 *
	 * Wire format (before base64url): identical to V2/V3.
	 *   magic[2] | IV[16] | attempt[1] | octalLen[4] | packed[N] | HMAC[32]
	 *   (octalLen field stores the packed-byte count, not an octal string length)
	 *
	 * HKDF info tag: 'BQC-secure-v4' — produces key material independent from V3.
	 *
	 * V1/V2/V3 ciphertexts remain fully decryptable.
	 */
	private const SECURE_MAGIC_V4 = "\x42\x55"; // ASCII 'BU'

	// ─── Legacy defaults (key = '') ──────────────────────────────────

	private const DEFAULT_ROT_L = 3;
	private const DEFAULT_ROT_R = 5;
	private const DEFAULT_ROUNDS = 3;
	private const DEFAULT_RUN_MAX = 4;

	/**
	 * Prefix sentinel digit.
	 *
	 * queueEncrypt emits only digits in {1..runMax} for 1-runs and
	 * {6..(5+runMax)} for 0-runs.  Since runMax <= 4, the digit '5' is
	 * never emitted and is safe as a sentinel.  Unlike '0', '5' as the
	 * leading digit of a decimal string is preserved through the
	 * decimal → octal → decimal numeric round-trip.
	 */
	private const PREFIX_SENTINEL = '5';

	// ─── S-box quality thresholds ────────────────────────────────────

	/**
	 * Minimum acceptable S-box nonlinearity.
	 *
	 * NL measures resistance to linear cryptanalysis.
	 * AES S-box: NL = 112  (GF(2^8) algebraic optimum)
	 * Random bijection average: NL ≈ 92
	 * Our threshold: NL >= 80  (rejects the weakest ~0.1% of candidates)
	 */
	private const SBOX_NL_THRESHOLD = 80;

	/**
	 * Maximum S-box regeneration attempts before accepting the best candidate.
	 * In practice, attempt 0 almost always satisfies the threshold.
	 */
	private const SBOX_MAX_ATTEMPTS = 16;

	// ─── Wire format layout offsets ──────────────────────────────────

	/** Byte offset where the IV starts in the wire format (after 2-byte magic). */
	private const WIRE_IV_OFFSET = 2;

	/** Length of the IV in bytes. */
	private const WIRE_IV_LEN = 16;

	/** Byte offset of the attempt counter in the wire format. */
	private const WIRE_ATT_OFFSET = 18;

	/** Byte offset where the 4-byte big-endian octalLen field starts. */
	private const WIRE_OCTAL_LEN_OFFSET = 19;

	/** Byte offset where the octal payload starts. */
	private const WIRE_OCTAL_OFFSET = 23;

	/** HMAC length for v2 format (full SHA-256). */
	private const HMAC_LEN_V2 = 32;

	/** HMAC length for v1 format (truncated SHA-256). */
	private const HMAC_LEN_V1 = 16;

	/**
	 * Minimum payload length for v2 secure mode.
	 * magic(2) + IV(16) + attempt(1) + octalLen(4) + octal(≥1) + HMAC(32) = 56
	 */
	private const MIN_PAYLOAD_V2 = 56;

	/**
	 * Minimum payload length for v1 secure mode.
	 * magic(2) + IV(16) + attempt(1) + octalLen(4) + octal(≥1) + HMAC(16) = 40
	 */
	private const MIN_PAYLOAD_V1 = 40;

	/**
	 * Minimum payload length for v3 secure mode.
	 * Wire format identical to v2: magic(2) + IV(16) + attempt(1) + octalLen(4) + octal(≥1) + HMAC(32) = 56
	 */
	private const MIN_PAYLOAD_V3 = 56;

	/**
	 * Minimum payload length for v4 secure mode.
	 * Wire format identical to V2/V3: magic(2)+IV(16)+attempt(1)+packedLen(4)+packed(≥1)+HMAC(32) = 56
	 */
	private const MIN_PAYLOAD_V4 = 56;

	// ─── Legacy 4-bit S-box (key = '') ───────────────────────────────

	/** Forward nibble S-box. */
	private const SBOX = [
		0x0 => 0xC,
		0x1 => 0x5,
		0x2 => 0x6,
		0x3 => 0xB,
		0x4 => 0x9,
		0x5 => 0x0,
		0x6 => 0xA,
		0x7 => 0xD,
		0x8 => 0x3,
		0x9 => 0xE,
		0xA => 0xF,
		0xB => 0x8,
		0xC => 0x4,
		0xD => 0x7,
		0xE => 0x1,
		0xF => 0x2,
	];

	/** Inverse nibble S-box. */
	private const SBOX_INV = [
		0x0 => 0x5,
		0x1 => 0xE,
		0x2 => 0xF,
		0x3 => 0x8,
		0x4 => 0xC,
		0x5 => 0x1,
		0x6 => 0x2,
		0x7 => 0xD,
		0x8 => 0xB,
		0x9 => 0x4,
		0xA => 0x6,
		0xB => 0x3,
		0xC => 0x0,
		0xD => 0x7,
		0xE => 0x9,
		0xF => 0xA,
	];

	// ─── AES S-box (Rijndael, GF(2^8), NL=112) ──────────────────────

	/**
	 * Standard AES (Rijndael) S-box — a bijection over GF(2^8).
	 *
	 * Constructed as: AES_SBOX[x] = affine_transform(GF_inverse(x))
	 * Nonlinearity NL = 112 — the algebraic optimum for 8-bit bijections
	 * (random bijections average NL ≈ 92; our HKDF-derived S-boxes ≥ 80).
	 *
	 * Used in V4 secure mode: composed with the HKDF-derived S-box so the
	 * effective key S-box inherits AES-level nonlinearity.
	 */
	private const AES_SBOX = [
