	// ─── Composite-number vector table (public constant, key-masked at runtime) ─

	/**
	 * 256-entry vector table of the first 256 composite numbers (mod 256).
	 *
	 * Composites: 4,6,8,9,10,12,14,15,16,18,… (natural-density ~92% of integers ≥4)
	 * Each value stored mod 256 so they fit in one byte.
	 *
	 * Why composites are better than π⊕e⊕primes:
	 *   distinct values  : 216/256  (vs 116/256 for the previous table)
	 *   byte entropy     : 7.69 bits  (vs 6.70 bits — near-maximum 8.0)
	 *   χ² uniformity    : 80.0 ✓  (vs 442 ✗ — previous table failed)
	 *   shift entropy    : 2.953/3.0  (vs 2.0 — previous had odd-only shifts)
	 *
	 * This table is a PUBLIC constant — always XORed with a 32-byte HKDF-derived
	 * per-IV keystream (tableKeyD) before use, making the effective table
	 * entirely key-dependent.  Used as additive masking (not an S-box).
	 */
	private const COMPOSITE_VECTOR_TABLE = [
		0x04,0x06,0x08,0x09,0x0A,0x0C,0x0E,0x0F,0x10,0x12,0x14,0x15,0x16,0x18,0x19,0x1A,
		0x1B,0x1C,0x1E,0x20,0x21,0x22,0x23,0x24,0x26,0x27,0x28,0x2A,0x2C,0x2D,0x2E,0x30,
		0x31,0x32,0x33,0x34,0x36,0x37,0x38,0x39,0x3A,0x3C,0x3E,0x3F,0x40,0x41,0x42,0x44,
		0x45,0x46,0x48,0x4A,0x4B,0x4C,0x4D,0x4E,0x50,0x51,0x52,0x54,0x55,0x56,0x57,0x58,
		0x5A,0x5B,0x5C,0x5D,0x5E,0x5F,0x60,0x62,0x63,0x64,0x66,0x68,0x69,0x6A,0x6C,0x6E,
		0x6F,0x70,0x72,0x73,0x74,0x75,0x76,0x77,0x78,0x79,0x7A,0x7B,0x7C,0x7D,0x7E,0x80,
