	// ─── Prime-gap + π digit − prime shift table ─────────────────────────

	/**
	 * 256-entry shift+XOR vector table.
	 *
	 * PRIME_GAP_PI_TABLE[i] = (PRIME_GAP_TABLE[i] + pi_digit[i] - prime[i] + 512) & 0xFF
	 *
	 *   PRIME_GAP_TABLE[i] : sum of composites between prime[i-1] and prime[i], mod 256
	 *   pi_digit[i]         : i-th decimal digit of π after the decimal point (0–9)
	 *   prime[i]            : i-th prime, mod 256
	 *
	 * Properties:
	 *   distinct  : 156 / 256  (not a bijection — used for additive masking only)
	 *   shift ent : 2.977 / 3.0  (near-uniform 0–7 coverage)
	 *   shift dist: [29,33,21,34,30,40,30,39]
	 *
	 * Replaces applyPrimeShiftXor's runtime 2048-prime double-lookup with a
	 * single 256-entry table lookup per byte.  Always XORed with tableKeyE
	 * (HKDF-derived per-IV keystream) before use, making the effective shift
	 * amounts fully key-dependent regardless of table structure.
	 *
	 * Performance gain over getPrimeTable()-based approach:
	 *   2–3× faster per call; eliminates 2048-element array from hot path.
	 *   Overall encrypt() impact: ~0.1–0.5% (FWHT NL check dominates at 98%).
	 */
