	/**
	 * Forward bit permutation: output_bit[BIT_PERM[i]] = input_bit[i]
	 * Shuffles bit positions within each byte to spread diffusion.
	 */
	private const BIT_PERM = [5, 0, 6, 1, 7, 2, 4, 3];

	/**
	 * Inverse bit permutation: output_bit[i] = input_bit[BIT_PERM[i]]
	 */
	private const BIT_PERM_INV = [1, 3, 5, 7, 6, 0, 2, 4];

	/**
	 * Forward 16-bit cross-byte bit permutation (V3, secure mode only).
	 * output_bit[ BIT_PERM_16[i] ] = input_bit[i]
	 *
	 * Operates on two consecutive bytes treated as a 16-bit word
	 * (bits 0–7 = low byte, bits 8–15 = high byte).  Exactly 8 of the
	 * 16 bits cross the byte boundary, ensuring every output byte
	 * contains bits from both input bytes.
	 *
	 * Crossing map (input byte → output byte):
	 *   bit  0 (byte 0) → pos 13 (byte 1)   bit  2 (byte 0) → pos 11 (byte 1)
	 *   bit  5 (byte 0) → pos 10 (byte 1)   bit  7 (byte 0) → pos 14 (byte 1)
	 *   bit  8 (byte 1) → pos  5 (byte 0)   bit 10 (byte 1) → pos  3 (byte 0)
	 *   bit 13 (byte 1) → pos  2 (byte 0)   bit 15 (byte 1) → pos  6 (byte 0)
	 */
	private const BIT_PERM_16 = [13, 4, 11, 0, 7, 10, 1, 14, 5, 12, 3, 8, 15, 2, 9, 6];

	/**
	 * Inverse of BIT_PERM_16.
	 * BIT_PERM_16_INV[ BIT_PERM_16[j] ] == j  for all j in 0..15
	 */
	private const BIT_PERM_16_INV = [3, 6, 13, 10, 1, 8, 15, 4, 11, 14, 5, 2, 9, 0, 7, 12];

