	/**
	 * Period-7 rotation sequence derived from a 3-bit maximal LFSR
	 * (primitive polynomial x³+x+1, recurrence s[n] = s[n-3] XOR s[n-1]).
	 *
	 * Visits every value in {1..7} exactly once per period. Used as the
	 * per-position rotation amount in the XOR cascade steps (3 and 6),
	 * replacing the fixed rotL / rotR scalars in V3 secure mode.
	 *
	 * Key property: gcd(7, 8) = 1, so the cascade orbit period becomes
	 * lcm(7, n) ≥ 56 bytes, eliminating the 8-byte differential orbit
	 * that existed with a fixed rotation (attack 1).
	 */
	private const LFSR_ROT_SEQ = [1, 2, 4, 3, 6, 7, 5];

	/**
	 * First 256 prime gaps: PRIME_GAPS_256[i] = prime[i+1] − prime[i].
	 *
	 * Used by applyPrimeGapSwap() to determine swap distances.
	 * The prime gap sequence is irregular (max=34, mean≈6.3) and coprime
	 * to typical block sizes, ensuring swap pairs are non-periodic and
	 * reach across cascade boundaries.
	 *
	 * Key property: at 1 round, prime-gap swap stabilises worst-case
	 * avalanche from min≈0.09 to min≈0.34 (3.6× improvement) by creating
	 * long-range byte connections that cascade alone cannot provide.
	 */
	private const PRIME_GAPS_256 = [
		 1, 2, 2, 4, 2, 4, 2, 4, 6, 2, 6, 4, 2, 4, 6, 6,
		 2, 6, 4, 2, 6, 4, 6, 8, 4, 2, 4, 2, 4,14, 4, 6,
		 2,10, 2, 6, 6, 4, 6, 6, 2,10, 2, 4, 2,12,12, 4,
		 2, 4, 6, 2,10, 6, 6, 6, 2, 6, 4, 2,10,14, 4, 2,
		 4,14, 6,10, 2, 4, 6, 8, 6, 6, 4, 6, 8, 4, 8,10,
