	// ─── 16-bit permutation LUT (lazy-initialised) ──────────────────

	/** @var int[]|null  Forward 16-bit permutation table (65 536 entries). */
	private static ?array $perm16Lut = null;

	/** @var int[]|null  Inverse 16-bit permutation table (65 536 entries). */
	private static ?array $unPerm16Lut = null;

	/**
	 * Lazy-initialise and return the forward 16-bit permutation LUT.
	 *
	 * PERM16_LUT[word] applies BIT_PERM_16 to a 16-bit value in O(1),
	 * replacing the 16-iteration bit loop in permuteWordPair().
	 * The 65 536-entry table is built once and cached in a static.
	 *
	 * @return int[]  Forward permutation table (65 536 entries)
	 */
	private static function getPerm16Lut(): array
	{
		if (self::$perm16Lut !== null) {
			return self::$perm16Lut;
		}
		$perm = self::BIT_PERM_16;
		$lut = [];
		for ($w = 0; $w < 65536; $w++) {
			$r = 0;
			for ($i = 0; $i < 16; $i++) {
				if (($w >> $i) & 1) {
					$r |= (1 << $perm[$i]);
				}
			}
			$lut[$w] = $r;
		}
		self::$perm16Lut = $lut;
		return $lut;
	}

	/**
	 * Lazy-initialise and return the inverse 16-bit permutation LUT.
	 *
	 * @return int[]  Inverse permutation table (65 536 entries)
	 */
	private static function getUnPerm16Lut(): array
	{
		if (self::$unPerm16Lut !== null) {
			return self::$unPerm16Lut;
		}
		$perm = self::BIT_PERM_16_INV;
		$lut = [];
		for ($w = 0; $w < 65536; $w++) {
			$r = 0;
			for ($i = 0; $i < 16; $i++) {
				if (($w >> $i) & 1) {
					$r |= (1 << $perm[$i]);
				}
			}
			$lut[$w] = $r;
		}
		self::$unPerm16Lut = $lut;
		return $lut;
	}

	// ─── Prime number table prefix (π(100000) = 9592 entries) ──────

	/**
	 * Number of primes up to 100,000, used for modular indexing.
	 * Period = 9592, ensuring the prime constant sequence never repeats
	 * within typical message sizes (up to ~200 bytes × 5 rounds × 47 stride).
	 */
	private const PRIME_TABLE_SIZE = 9592;

	/**
	 * XOR-mixed low bytes of the first 9592 prime numbers (2 .. 99991).
