	/**
	 * Forward prime S-box: a permutation of 0..255 derived via
	 * Fisher-Yates shuffle seeded by primes with golden-ratio mixing.
	 *
	 * NL = 84 standalone; composed with key-derived S-box: NL ≈ 92.
	 * The number-theoretic origin provides structural diversity from
	 * the HKDF-derived S-box.
	 */

