		0x00,0x41,0x00,0xEB,0x00,0x0D,0x00,0xF7,0x00,0x79,0x00,0xE3,0x00,0x05,0x00,0x2F,
		0x00,0x31,0x00,0x5B,0x00,0x7D,0x00,0xE7,0x00,0x69,0x00,0x53,0x00,0x75,0x00,0x1F,
		0x00,0x21,0x00,0xCB,0x00,0xED,0x00,0xD7,0x00,0x59,0x00,0xC3,0x00,0xE5,0x00,0x0F,
		0x00,0x11,0x00,0x3B,0x00,0x5D,0x00,0xC7,0x00,0x49,0x00,0x33,0x00,0x55,0x00,0xFF,
	];

	// ─── Hex ↔ binary lookup tables ──────────────────────────────────

	/** @var array<string,string> One hex digit → four binary digits. */
	private const HEX_TO_BIN_MAP = [
		'0' => '0000',
		'1' => '0001',
		'2' => '0010',
		'3' => '0011',
		'4' => '0100',
		'5' => '0101',
		'6' => '0110',
		'7' => '0111',
		'8' => '1000',
		'9' => '1001',
		'a' => '1010',
		'b' => '1011',
		'c' => '1100',
		'd' => '1101',
		'e' => '1110',
		'f' => '1111',
	];

	/** @var array<string,string> Four binary digits → one hex digit. */
	private const BIN_TO_HEX_MAP = [
		'0000' => '0',
		'0001' => '1',
		'0010' => '2',
		'0011' => '3',
		'0100' => '4',
		'0101' => '5',
		'0110' => '6',
