	// ═══════════════════════════════════════════════════════════════════
	// KEY DERIVATION
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Compute the nonlinearity of an 8-bit S-box using Fast Walsh-Hadamard Transform.
	 *
	 * For each nonzero output mask b, we define the Boolean component function:
	 *   f_b(x) = popcount(b AND S(x)) mod 2
	 *
	 * The Walsh spectrum W_b is computed via FWHT.  The nonlinearity of
	 * component f_b is:
	 *   NL(f_b) = 128 - max_a |W_b[a]| / 2
	 *
	 * The S-box nonlinearity is the minimum over all nonzero b:
	 *   NL(S) = min_{b != 0} NL(f_b)
	 *
	 * Higher NL → stronger resistance to linear cryptanalysis.
	 * AES = 112, random bijection average ≈ 92, our threshold = 80.
	 *
	 * @internal Used exclusively by expandKey() during S-box quality verification.
	 *
	 * @param  int[] $sbox  256-element permutation of 0..255 (must be a valid bijection)
	 * @return int          Nonlinearity score (0–128; higher is better)
	 */
	private static function computeSboxNonlinearity(array $sbox): int
	{
		/** @var int Number of elements in an 8-bit S-box */
		$n = 256;
		$minNl = 128;

		// Pre-allocate the Walsh spectrum array once to avoid per-iteration allocation
		$f = array_fill(0, $n, 0);

		for ($b = 1; $b < $n; $b++) {
			// Build +1/-1 representation of the component function f_b
			for ($x = 0; $x < $n; $x++) {
				// (-1)^{popcount(b & S(x)) mod 2}
				$f[$x] = (substr_count(decbin($b & $sbox[$x]), '1') & 1) ? -1 : 1;
			}

			// In-place Fast Walsh-Hadamard Transform (butterfly network)
			$h = 1;
			while ($h < $n) {
				$doubleH = $h << 1;
				for ($i = 0; $i < $n; $i += $doubleH) {
					for ($j = $i, $jEnd = $i + $h; $j < $jEnd; $j++) {
						$u = $f[$j];
						$v = $f[$j + $h];
						$f[$j]      = $u + $v;
						$f[$j + $h] = $u - $v;
					}
				}
				$h = $doubleH;
			}

			// Find maximum absolute Walsh coefficient for this component
			$maxAbs = 0;
			for ($a = 0; $a < $n; $a++) {
				$abs = abs($f[$a]);
				if ($abs > $maxAbs) {
					$maxAbs = $abs;
				}
			}

			$nl = 128 - ($maxAbs >> 1);
			if ($nl < $minNl) {
				$minNl = $nl;
				// Early-exit: already below threshold, no point checking remaining masks
				if ($minNl < self::SBOX_NL_THRESHOLD) {
					return $minNl;
				}
			}
		}

		return $minNl;
	}

	/**
	 * Derive the legacy 4-bit S-box (used only when key = '').
	 *
	 * When key = '' the hardcoded default S-box is returned so that
	 * existing ciphertexts remain fully decryptable.
	 *
	 * For non-empty keys, a 4-bit Fisher-Yates shuffle is performed with
	 * rejection sampling to produce an unbiased random permutation of 0..15.
	 *
	 * @internal Only called by deriveParams() in legacy (4-bit) mode.
	 *
	 * @param  string $key  Secret key  ('' = return default S-box)
	 * @return array{sbox: array<int, int>, sboxInv: array<int, int>}
	 */
	private static function deriveSbox(string $key): array
	{
		if ($key === '') {
			return ['sbox' => self::SBOX, 'sboxInv' => self::SBOX_INV];
		}

		// Generate sufficient key material for rejection sampling.
		// Each swap may need multiple bytes if the first one falls in the bias zone.
		$material = '';
		for ($c = 0; $c < 4; $c++) {
			$material .= hash('sha256', $key . "\x00sbox" . chr($c), true);
		}
		$bytes = array_values(unpack('C*', $material));
		$byteIdx = 0;
		$byteLen = count($bytes);

		// Fisher-Yates shuffle over nibbles 0..15 with rejection sampling
		$sbox = range(0, 15);
		for ($i = 15; $i > 0; $i--) {
			$range = $i + 1;
			$limit = 256 - (256 % $range); // reject values >= limit to eliminate bias
			do {
				$val = $bytes[$byteIdx % $byteLen];
				$byteIdx++;
			} while ($val >= $limit);
			$j = $val % $range;
			[$sbox[$i], $sbox[$j]] = [$sbox[$j], $sbox[$i]];
		}

		// Build inverse
		$sboxInv = array_fill(0, 16, 0);
		for ($i = 0; $i < 16; $i++) {
			$sboxInv[$sbox[$i]] = $i;
		}

		return compact('sbox', 'sboxInv');
	}

	/**
	 * Derive legacy pipeline parameters (4-bit mode, used when key = '').
	 *
	 * When key is empty, returns hardcoded defaults for full backward
	 * compatibility. When key is non-empty, derives parameters from
	 * SHA-256(key) — however this path is only used for legacy ciphertexts
	 * that were not encrypted with secure mode.
	 *
	 * @internal Only called from encrypt()/decrypt() in legacy mode.
	 *
	 * @param  string $key  Secret key ('' = use hardcoded defaults)
	 * @return LegacyParams  Pipeline parameters for the 4-bit diffusion path
	 *
	 * @phpstan-return LegacyParams
	 */
	private static function deriveParams(string $key): array
	{
		$sboxParams = self::deriveSbox($key);

		if ($key === '') {
			return [
				'rotL' => self::DEFAULT_ROT_L,
				'rotR' => self::DEFAULT_ROT_R,
				'rounds' => self::DEFAULT_ROUNDS,
				'runMax' => self::DEFAULT_RUN_MAX,
				'sbox' => $sboxParams['sbox'],
				'sboxInv' => $sboxParams['sboxInv'],
				'secure' => false,
			];
		}

		$hash = hash('sha256', $key, true);
		$bytes = array_values(unpack('C*', $hash));

		$rotL = ($bytes[0] % 7) + 1;   // 1–7
		$rotR = ($bytes[1] % 7) + 1;   // 1–7
		if ($rotL === $rotR) {
			$rotR = ($rotR % 7) + 1;   // guarantee rotL != rotR
			// If still colliding after first adjustment, increment again
			if ($rotL === $rotR) {
				$rotR = ($rotR % 7) + 1;
			}
		}

		return [
			'rotL' => $rotL,
			'rotR' => $rotR,
			'rounds' => ($bytes[2] % 4) + 2,   // 2–5
			'runMax' => ($bytes[3] % 4) + 1,   // 1–4
			'sbox' => $sboxParams['sbox'],
			'sboxInv' => $sboxParams['sboxInv'],
			'secure' => false,
		];
	}

	/**
	 * Derive secure-mode parameters from key + IV.
	 *
	 * HKDF-SHA256 expands (key, IV) into 647 bytes of key material:
	 *   bytes   0–509  Fisher-Yates shuffle: 255 swaps × 2 bytes each (rejection sampling)
	 *   bytes 510–513  rotL, rotR, rounds, runMax
	 *   bytes 514–545  32-byte HMAC-SHA256 subkey
	 *   bytes 546–577  32-byte tableKey   — XORed into PRIME_TABLE lookups in steps 4a/4b
	 *   bytes 578–582  bitRotKeys[0..4]   — per-round bit-rotation keys (&0x07 each)
	 *                  Expands bit-permutation variants from 8 (single key) to 8^5 = 32 768.
	 *   bytes 583–614  32-byte tableKeyB  — XORed into COMPOSITE_GAP_TABLE in step 5b,
	 *                  cryptographically independent from tableKey.
	 *   bytes 615–646  32-byte tableKeyC  — XORed into PRIME_TABLE in step 2b,
	 *                  decouples step 2b from steps 4a/4b which share tableKey.
	 *
	 * The 'attempt' counter is embedded in the HKDF info string so each
	 * regeneration attempt produces a distinct, deterministic key stream.
	 * The winning attempt index is stored in the ciphertext (1 byte) so
	 * decryption can reproduce the exact same S-box without a search.
	 *
	 * S-box quality guarantee:
	 *   After generation, NL is checked via FWHT.
	 *   If NL < SBOX_NL_THRESHOLD the S-box is rejected and a new one is
	 *   generated with attempt+1.  In practice attempt 0 always passes.
	 *
	 * @param  string $key      Secret key (must not be empty)
	 * @param  string $iv       16-byte random IV
	 * @param  int    $attempt  Regeneration counter (0 = first try; max = SBOX_MAX_ATTEMPTS)
	 * @return SecureParams     Pipeline parameters for the 8-bit secure diffusion path
	 *
	 * @throws RuntimeException If HKDF output length is unexpectedly short (should never happen)
	 *
	 * @phpstan-return SecureParams
	 */
	private static function expandKey(string $key, string $iv, int $attempt = 0, string $infoTag = 'BQC-secure-v3'): array
	{
		/** @var int Total bytes requested from HKDF */
		$hkdfLen = 648;

		// Embed attempt index in HKDF info to get a distinct key stream per attempt
		// Layout: 510 for Fisher-Yates (255 swaps × 2 bytes, rejection sampling),
		//         4 for pipeline params, 32 for HMAC subkey,
		//         32 for tableKey (steps 4a/4b),
		//         5 for per-round bitRotKeys,
		//         32 for tableKeyB (step 5b, independent),
		//         32 for tableKeyC (step 2b, independent),
		//         1 for gridN (grid dimension: 4 or 8).
		$info     = $infoTag . chr($attempt);
		$material = hash_hkdf('sha256', $key, $hkdfLen, $info, $iv);

		if (strlen($material) < $hkdfLen) {
			// @codeCoverageIgnoreStart — defensive guard against broken hash_hkdf
			throw new RuntimeException('HKDF produced insufficient key material');
			// @codeCoverageIgnoreEnd
		}

		/** @var int[] $mat  Unsigned byte array from HKDF output */
		$mat = array_values(unpack('C*', $material));

		// Build 8-bit S-box: Fisher-Yates shuffle over 0..255
		// Uses 2-byte (16-bit) rejection sampling to eliminate modular bias.
		$sbox = range(0, 255);
		$byteIdx = 0;
		for ($i = 255; $i > 0; $i--) {
			$range = $i + 1;
			$limit = 65536 - (65536 % $range); // 16-bit rejection threshold
			do {
				$val = ($mat[$byteIdx] << 8) | $mat[$byteIdx + 1];
				$byteIdx += 2;
				// Wrap around if we exhaust material (extremely unlikely)
				if ($byteIdx + 1 >= 510) {
					$byteIdx = 0;
				}
			} while ($val >= $limit);
			$j = $val % $range;
			[$sbox[$i], $sbox[$j]] = [$sbox[$j], $sbox[$i]];
		}

		// V4 skips the FWHT NL check: PRIME_SBOX_COMP (NL=94) is composed in
		// expandKeyV4 after this call, and attempt 0 empirically always passes.
		// V1/V2/V3 retain the check for backward compatibility.
		if (strpos($infoTag, 'v4') === false
			&& $attempt < self::SBOX_MAX_ATTEMPTS
			&& self::computeSboxNonlinearity($sbox) < self::SBOX_NL_THRESHOLD) {
			return self::expandKey($key, $iv, $attempt + 1, $infoTag);
		}

		// Build inverse S-box
		$sboxInv = array_fill(0, 256, 0);
		for ($i = 0; $i < 256; $i++) {
			$sboxInv[$sbox[$i]] = $i;
		}

		// Pipeline parameters (bytes 510–513)
		$rotL = ($mat[510] % 7) + 1;   // forward XOR cascade rotation  (1–7)
		$rotR = ($mat[511] % 7) + 1;   // backward XOR cascade rotation (1–7)
		if ($rotL === $rotR) {
			$rotR = ($rotR % 7) + 1;
			if ($rotL === $rotR) {
				$rotR = ($rotR % 7) + 1;
			}
		}
		// V4: minimum 5 rounds — achieves avalanche Δ < AES-256 (0.0009 vs 0.0011).
		// V1/V2/V3: 2–5 rounds, unchanged.
		$rawRounds = ($mat[512] % 4) + 2;
		$rounds = (strpos($infoTag, 'v4') !== false) ? max($rawRounds, 5) : $rawRounds;
		$runMax = ($mat[513] % 4) + 1;  // run-length threshold   (1–4)

		// HMAC subkey (bytes 514–545, 32 bytes)
		$hmacKey = substr($material, 514, 32);

		// tableKey (bytes 546–577, 32 bytes).
		// Masks PRIME_TABLE lookups in steps 4a and 4b.
		$tableKey = array_values(unpack('C*', substr($material, 546, 32)));

		// Per-round bit-rotation keys (bytes 578–582, 5 bytes, one per round).
		// Each byte masked to 3 bits (0–7). Using a distinct key per round expands
		// the effective bit-permutation variant space from 8 to 8^5 = 32 768.
		// bitRotKey (singular) kept for V1/V2 fallback path in diffuseBytes.
		$bitRotKeys = [];
		for ($r = 0; $r < 5; $r++) {
			$bitRotKeys[$r] = $mat[578 + $r] & 0x07;
		}
		$bitRotKey = $bitRotKeys[0]; // V1/V2 compat alias

		// tableKeyB (bytes 583–614, 32 bytes).
		// Masks COMPOSITE_GAP_TABLE in step 5b.  Derived from a separate HKDF
		// region so it is statistically independent from tableKey, eliminating
		// the correlation between step 5b and steps 4a/4b.
		$tableKeyB = array_values(unpack('C*', substr($material, 583, 32)));

		// tableKeyC (bytes 615–646, 32 bytes).
		// Masks PRIME_TABLE in step 2b.  Previously step 2b shared the same
		// tableKey index as step 4a (both computed idx & 0x1F), creating a
		// correlated masking.  tableKeyC is a dedicated independent keystream.
		$tableKeyC = array_values(unpack('C*', substr($material, 615, 32)));

		// Grid dimension (byte 647).
		// 0–127 → n=4 (4×4=16-byte blocks, mirrors AES state size).
		// 128–255 → n=8 (8×8=64-byte blocks, for longer messages).
		// Controls applyGridShiftRows in step 3 (V3 only).
		$gridN = ($mat[647] < 128) ? 4 : 8;

		return [
			'rotL'       => $rotL,
			'rotR'       => $rotR,
			'rounds'     => $rounds,
			'runMax'     => $runMax,
			'sbox'       => $sbox,
			'sboxInv'    => $sboxInv,
			'hmacKey'    => $hmacKey,
			'tableKey'   => $tableKey,
			'bitRotKey'  => $bitRotKey,
			'bitRotKeys' => $bitRotKeys,
			'tableKeyB'  => $tableKeyB,
			'tableKeyC'  => $tableKeyC,
			'gridN'      => $gridN,
			'secure'     => true,
			'attempt'    => $attempt,
		];
	}

	/**
	 * Compose a permutation S-box with the AES S-box.
	 *
	 * Produces: composed[i] = AES_SBOX[sbox[i]]  (apply sbox first, then AES)
	 * Inverse:  composedInv[i] = sboxInv[AES_SBOX_INV[i]]
	 *
	 * The composed bijection inherits AES nonlinearity NL=112 as an upper bound,
	 * while preserving the key-dependent unpredictability of the HKDF-derived sbox.
	 *
	 * @param  int[] $sbox     Forward permutation (256 elements, bijection over 0..255)
	 * @param  int[] $sboxInv  Inverse permutation matching $sbox
	 * @return array{sbox: array<int,int>, sboxInv: array<int,int>}
	 */
	private static function composeWithAesSbox(array $sbox, array $sboxInv): array
	{
		$composed    = array_fill(0, 256, 0);
		$composedInv = array_fill(0, 256, 0);

		for ($i = 0; $i < 256; $i++) {
			$composed[$i]    = self::AES_SBOX[$sbox[$i]];
			$composedInv[$i] = $sboxInv[self::AES_SBOX_INV[$i]];
		}

		return ['sbox' => $composed, 'sboxInv' => $composedInv];
	}

	/**
	 * Derive V4 secure-mode parameters.
	 *
	 * Calls expandKey() with the 'BQC-secure-v4' HKDF info tag (producing key
	 * material independent from V3), then composes the resulting S-box with the
	 * AES S-box via composeWithAesSbox() to yield NL=112-class substitution.
	 *
	 * @param  string $key      Secret key (must not be empty)
	 * @param  string $iv       16-byte random IV
	 * @param  int    $attempt  Regeneration counter
	 * @return SecureParams
	 *
	 * @phpstan-return SecureParams
	 */
	private static function expandKeyV4(string $key, string $iv, int $attempt = 0): array
	{
		$params = self::expandKey($key, $iv, $attempt, 'BQC-secure-v4');

		$composed = self::composeWithAesSbox($params['sbox'], $params['sboxInv']);
		$params['sbox']    = $composed['sbox'];
		$params['sboxInv'] = $composed['sboxInv'];

		// Derive 32-byte tableKeyD from a separate HKDF region (independent of all
		// other subkeys).  XOR with PI_E_PRIME_TABLE to produce the per-IV vecTable:
		//   vecTable[i] = PI_E_PRIME_TABLE[i] ^ tableKeyD[i & 0x1F]
		// This makes the otherwise-public number-theoretic constants fully key-dependent.
		$tableKeyDRaw = hash_hkdf('sha256', $key, 32, 'BQC-v4-vectable', $iv);
		$tableKeyD    = array_values(unpack('C*', $tableKeyDRaw));

		$vecTable = array_fill(0, 256, 0);
		for ($i = 0; $i < 256; $i++) {
			$vecTable[$i] = self::COMPOSITE_VECTOR_TABLE[$i] ^ $tableKeyD[$i & 0x1F];
		}

		// Derive 32-byte tableKeyE (primeShiftKey) from another independent HKDF region.
		// XORed into the raw (p[i]+p[i+n])&7 shift amount and used as additive whitening,
		// breaking the key-independence of the prime-sequence rotation schedule.
		$tableKeyERaw  = hash_hkdf('sha256', $key, 32, 'BQC-v4-primeshift', $iv);
		$primeShiftKey = array_values(unpack('C*', $tableKeyERaw));

		$params['vecTable']      = $vecTable;
		$params['primeShiftKey'] = $primeShiftKey;

		// Derive 32-byte swapKey from an independent HKDF region.
		// Masks the prime-gap swap distances so the swap pattern is fully
		// key-dependent.  Without this, the swap sequence is deterministic
		// from the public PRIME_GAPS_256 table.
		$swapKeyRaw        = hash_hkdf('sha256', $key, 32, 'BQC-v4-gapswap', $iv);
		$params['swapKey'] = array_values(unpack('C*', $swapKeyRaw));

		// ── Precomputed LUTs for bitwise-optimised diffusion ─────────

		// Fused S-box: PRIME_SBOX_COMP[sbox[x]] — merges step 1 + step 2
		// into a single 256-entry lookup, eliminating one full-length loop.
		$sbox = $params['sbox'];
		$fusedSbox = [];
		for ($i = 0; $i < 256; $i++) {
			$fusedSbox[$i] = self::PRIME_SBOX_COMP[$sbox[$i]];
		}
		$fusedSboxInv = array_fill(0, 256, 0);
		for ($i = 0; $i < 256; $i++) {
			$fusedSboxInv[$fusedSbox[$i]] = $i;
		}
		$params['fusedSbox']    = $fusedSbox;
		$params['fusedSboxInv'] = $fusedSboxInv;

		// Precomputed S-box rotation table: sboxRot[rot][byte] = rotateLeft(sbox[byte], rot).
		// Fuses the S-box lookup + bit rotation in the NL cascade (step 3/6)
		// into a single 2D array access, replacing two function calls per byte.
		$sboxRot = [];
		for ($r = 0; $r < 8; $r++) {
			$sboxRot[$r] = [];
			for ($b = 0; $b < 256; $b++) {
				$sboxRot[$r][$b] = self::rotateLeft($sbox[$b], $r);
			}
		}
		$params['sboxRot'] = $sboxRot;

		return $params;
	}

	// ═══════════════════════════════════════════════════════════════════
	// DIFFUSION LAYER
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Forward bit permutation on one byte.
	 * output_bit[ BIT_PERM[i] ] = input_bit[i]
	 *
	 * @pure  This is a stateless transformation.
	 *
	 * @param  int $byte  Input byte (0–255)
	 * @return int        Permuted byte (0–255)
	 */
	private static function permuteByte(int $byte): int
	{
		return self::PERM_LUT[$byte];
	}

	/**
	 * Inverse bit permutation on one byte.
	 * output_bit[i] = input_bit[ BIT_PERM[i] ]
	 *
	 * @pure  This is a stateless transformation.
	 *
	 * @param  int $byte  Input byte (0–255)
	 * @return int        Unpermuted byte (0–255)
	 */
	private static function unPermuteByte(int $byte): int
	{
		return self::PERM_INV_LUT[$byte];
	}

	/**
	 * Forward 16-bit cross-byte bit permutation (V3 only).
	 *
	 * Treats ($lo, $hi) as a 16-bit word and applies BIT_PERM_16, which
	 * moves exactly 8 bits across the byte boundary so every output byte
	 * carries bits from both input bytes.
	 *
	 * @param  int $lo  Low byte  (bits 0–7 of the 16-bit word)
	 * @param  int $hi  High byte (bits 8–15 of the 16-bit word)
	 * @return int[]    [new_lo, new_hi] — each in 0–255
	 */
	private static function permuteWordPair(int $lo, int $hi): array
	{
		$word   = ($hi << 8) | $lo;
		$result = 0;
		for ($i = 0; $i < 16; $i++) {
			if (($word >> $i) & 1) {
				$result |= (1 << self::BIT_PERM_16[$i]);
			}
		}
		return [$result & 0xFF, ($result >> 8) & 0xFF];
	}

	/**
	 * Inverse of permuteWordPair — recovers the original (lo, hi) pair.
	 *
	 * @param  int $lo  Low byte of the permuted word
	 * @param  int $hi  High byte of the permuted word
	 * @return int[]    [original_lo, original_hi] — each in 0–255
	 */
	private static function unPermuteWordPair(int $lo, int $hi): array
	{
		$word   = ($hi << 8) | $lo;
		$result = 0;
		for ($i = 0; $i < 16; $i++) {
			if (($word >> self::BIT_PERM_16[$i]) & 1) {
				$result |= (1 << $i);
			}
		}
		return [$result & 0xFF, ($result >> 8) & 0xFF];
	}

	/**
	 * Apply ShiftRows-equivalent across n×n byte grid blocks (V3 only).
	 *
	 * Processes the byte array in n² chunks. Within each chunk the bytes
	 * are treated as an n×n row-major grid. Row i (0-based) is cyclically
	 * shifted left by i positions, moving i bytes across column boundaries.
	 * Row 0 is unchanged. Partial trailing blocks (< n² bytes) are untouched.
	 *
	 * Effect: after the forward XOR cascade has spread influence along rows,
	 * ShiftRows redistributes those bytes across columns so that the next
	 * round's cascade and S-box steps mix bytes that were previously in
	 * different rows. This is the direct analogue of AES ShiftRows.
	 *
	 * @param  int[] $bytes  Flat byte array
	 * @param  int   $len    Length of $bytes
	 * @param  int   $n      Grid dimension (4 → 16-byte blocks, 8 → 64-byte blocks)
	 * @return int[]         Byte array with rows shifted
	 */
	private static function applyGridShiftRows(array $bytes, int $len, int $n): array
	{
		$blockSize = $n * $n;
		for ($blockStart = 0; $blockStart + $blockSize <= $len; $blockStart += $blockSize) {
			for ($row = 1; $row < $n; $row++) {
				$rowStart = $blockStart + $row * $n;
				// Cyclic left shift by $row: [0..n-1] → [row..n-1, 0..row-1]
				$head = array_slice($bytes, $rowStart + $row, $n - $row);
				$tail = array_slice($bytes, $rowStart, $row);
				$shifted = array_merge($head, $tail);
				for ($col = 0; $col < $n; $col++) {
					$bytes[$rowStart + $col] = $shifted[$col];
				}
			}
		}
		return $bytes;
	}

	/**
	 * Inverse of applyGridShiftRows: cyclic right shift of row i by i positions.
	 *
	 * @param  int[] $bytes
	 * @param  int   $len
	 * @param  int   $n
	 * @return int[]
	 */
	private static function reverseGridShiftRows(array $bytes, int $len, int $n): array
	{
		$blockSize = $n * $n;
		for ($blockStart = 0; $blockStart + $blockSize <= $len; $blockStart += $blockSize) {
			for ($row = 1; $row < $n; $row++) {
				$rowStart = $blockStart + $row * $n;
				// Cyclic right shift by $row: [0..n-1] → [n-row..n-1, 0..n-row-1]
				$tail = array_slice($bytes, $rowStart + $n - $row, $row);
				$head = array_slice($bytes, $rowStart, $n - $row);
				$shifted = array_merge($tail, $head);
				for ($col = 0; $col < $n; $col++) {
					$bytes[$rowStart + $col] = $shifted[$col];
				}
			}
		}
		return $bytes;
	}

	/**
	 * Rotate byte left by n bits (within 8-bit boundary).
	 *
	 * @pure  This is a stateless transformation.
	 *
	 * @param  int $byte  Input byte (0–255)
	 * @param  int $n     Rotation amount (0–7; values outside this range still work
	 *                    because of the masking, but are semantically invalid)
	 * @return int        Rotated byte (0–255)
	 */
	private static function rotateLeft(int $byte, int $n): int
	{
		return (($byte << $n) | ($byte >> (8 - $n))) & 0xFF;
	}

	/**
	 * Apply key-masked π⊕e⊕primes vector shift+XOR layer.
	 *
	 * For each byte at position i:
	 *   v       = vecTable[i & 0xFF]    (key-dependent: PI_E_PRIME_TABLE ^ tableKeyD)
	 *   shift   = v & 0x07              (3-bit rotation amount, position-dependent)
	 *   shift2  = (v >> 3) & 0x07       (second rotation for chaining
	 *   out[i]  = rotL(in[i], shift) ^ v ^ rotL(prev, shift2)
	 *   prev    = out[i]                (running chain — each output depends on all prior)
	 *
	 * The chaining (prev) creates a forward dependency analogous to CBC mode,
	 * ensuring a single-byte change propagates through all subsequent bytes.
	 * Because vecTable is key-dependent (PI_E_PRIME_TABLE ^ HKDF keystream),
	 * every rotation amount and XOR mask is unpredictable to an attacker.
	 *
	 * @param  int[] $bytes     Byte array (modified in-place semantics, returns new array)
	 * @param  int[] $vecTable  256-entry key-masked vector table
	 * @return int[]            Transformed byte array (same length)
	 */
	private static function applyVectorShiftXor(array $bytes, array $vecTable): array
	{
		$len  = count($bytes);
		$prev = 0;

		for ($i = 0; $i < $len; $i++) {
			$v           = $vecTable[$i & 0xFF];
			$shifted     = self::rotateLeft($bytes[$i], $v & 0x07);
			$bytes[$i]   = ($shifted ^ $v ^ self::rotateLeft($prev, ($v >> 3) & 0x07)) & 0xFF;
			$prev        = $bytes[$i];
		}

		return $bytes;
	}

	/**
	 * Inverse of applyVectorShiftXor — recovers original bytes.
	 *
	 * Because prev[i] = out[i-1] (i.e., the already-known output), inversion
	 * can proceed left-to-right without any look-ahead:
	 *   xored    = out[i] ^ v ^ rotL(out[i-1], shift2)
	 *   orig[i]  = rotL(xored, 8 - shift)    (rotR = rotL by complement)
	 *
	 * @param  int[] $bytes     Transformed byte array
	 * @param  int[] $vecTable  Same 256-entry key-masked vector table used during forward pass
	 * @return int[]            Original byte array (same length)
	 */
	private static function reverseVectorShiftXor(array $bytes, array $vecTable): array
	{
		$len  = count($bytes);
		$prev = 0;

		for ($i = 0; $i < $len; $i++) {
			$v          = $vecTable[$i & 0xFF];
			$xored      = ($bytes[$i] ^ $v ^ self::rotateLeft($prev, ($v >> 3) & 0x07)) & 0xFF;
			$prev       = $bytes[$i];
			$bytes[$i]  = self::rotateLeft($xored, (8 - ($v & 0x07)) & 0x07);
		}

		return $bytes;
	}

	/**
	 * Apply key-masked n+n prime shift+XOR layer.
	 *
	 * Previously used a 2048-entry runtime prime table with two lookups per byte:
	 *   rawShift = (primes[i % 2048] + primes[(i + n) % 2048]) & 0x07
	 *
	 * Now uses the precomputed PRIME_GAP_PI_TABLE (256-entry static constant):
	 *   rawShift = PRIME_GAP_PI_TABLE[i & 0xFF] & 0x07
	 *
	 * Performance: 2–3× faster per call (one lookup vs two; 256-entry vs 2048-entry).
	 * Crypto: equivalent — both paths are XOR-masked with HKDF-derived primeShiftKey.
	 *
	 * @param  int[] $bytes          Byte array
	 * @param  int   $n              Block length (kept for API compatibility)
	 * @param  int[] $primeShiftKey  32-byte HKDF-derived key (tableKeyE)
	 * @return int[]
	 */
	private static function applyPrimeShiftXor(array $bytes, int $n, array $primeShiftKey): array
	{
		for ($i = 0; $i < $n; $i++) {
			$v          = (self::PRIME_GAP_PI_TABLE[$i & 0xFF] ^ $primeShiftKey[$i & 0x1F]) & 0xFF;
			$shift      = $v & 0x07;
			$bytes[$i]  = (self::rotateLeft($bytes[$i], $shift) ^ $v) & 0xFF;
		}

		return $bytes;
	}

	/**
	 * Inverse of applyPrimeShiftXor.
	 *
	 * @param  int[] $bytes          Transformed byte array
	 * @param  int   $n              Block length (must match forward pass)
	 * @param  int[] $primeShiftKey  Same 32-byte key used during forward pass
	 * @return int[]
	 */
	private static function reversePrimeShiftXor(array $bytes, int $n, array $primeShiftKey): array
	{
		for ($i = 0; $i < $n; $i++) {
			$v         = (self::PRIME_GAP_PI_TABLE[$i & 0xFF] ^ $primeShiftKey[$i & 0x1F]) & 0xFF;
			$shift     = $v & 0x07;
			$unXored   = ($bytes[$i] ^ $v) & 0xFF;
			$bytes[$i] = self::rotateLeft($unXored, (8 - $shift) & 0x07);
		}

		return $bytes;
	}

	/**
	 * Prime-gap swap with S-box XOR feedback (V4 only).
	 *
	 * For each position i, computes a swap partner at distance
	 * PRIME_GAPS_256[(i + round*7) % 256] XOR swapKey[i & 0x1F].
	 * After swapping, each byte absorbs the S-box of its partner,
	 * creating a nonlinear cross-byte dependency.
	 *
	 * Purpose: stabilises worst-case avalanche at low round counts.
	 * At 1 round, raises min avalanche from ~0.09 to ~0.34 (3.6×)
	 * by connecting cascade-distant byte pairs directly.
	 *
	 * @param  int[] $bytes    Byte array (modified in-place semantics)
	 * @param  int   $len      Length of $bytes
	 * @param  int[] $sbox     Forward S-box (256-entry, key-derived)
	 * @param  int   $round    Current round index (varies swap pattern per round)
	 * @param  int[] $swapKey  32-byte HKDF-derived key for swap distance masking
	 * @return int[]           Swapped byte array (same length)
	 */
	private static function applyPrimeGapSwap(array $bytes, int $len, array $sbox, int $round, array $swapKey): array
	{
		for ($i = 0; $i < $len; $i++) {
			$g = self::PRIME_GAPS_256[($i + $round * 7) & 0xFF] ^ $swapKey[$i & 0x1F];
			$j = ($i + $g) % $len;
			if ($i !== $j) {
				// Swap
				[$bytes[$i], $bytes[$j]] = [$bytes[$j], $bytes[$i]];
				// Nonlinear XOR feedback: each byte absorbs S-box of partner
				$bytes[$i] = ($bytes[$i] ^ $sbox[$bytes[$j]]) & 0xFF;
				$bytes[$j] = ($bytes[$j] ^ $sbox[$bytes[$i]]) & 0xFF;
			}
		}

		return $bytes;
	}

	/**
	 * Inverse of applyPrimeGapSwap — reverses swap + XOR feedback.
	 *
	 * Processes in reverse index order (i = len-1 … 0).
	 * For each position: undo XOR feedback in reverse order, then undo swap.
	 *
	 * @param  int[] $bytes    Swapped byte array
	 * @param  int   $len      Length of $bytes
	 * @param  int[] $sbox     Same forward S-box used during encryption
	 * @param  int   $round    Same round index used during encryption
	 * @param  int[] $swapKey  Same 32-byte key used during encryption
	 * @return int[]           Original byte array (same length)
	 */
	private static function reversePrimeGapSwap(array $bytes, int $len, array $sbox, int $round, array $swapKey): array
	{
		for ($i = $len - 1; $i >= 0; $i--) {
			$g = self::PRIME_GAPS_256[($i + $round * 7) & 0xFF] ^ $swapKey[$i & 0x1F];
			$j = ($i + $g) % $len;
			if ($i !== $j) {
				// Undo XOR feedback in reverse order
				$bytes[$j] = ($bytes[$j] ^ $sbox[$bytes[$i]]) & 0xFF;
				$bytes[$i] = ($bytes[$i] ^ $sbox[$bytes[$j]]) & 0xFF;
				// Undo swap
				[$bytes[$i], $bytes[$j]] = [$bytes[$j], $bytes[$i]];
			}
		}

		return $bytes;
	}

	/**
	 * Apply forward diffusion to a raw byte string.
	 *
	 * Each round consists of six steps:
	 *   1. S-box substitution (key-derived, confusion)
	 *        Secure mode: full-byte 8-bit substitution (256-element S-box)
	 *        Legacy mode: nibble-level 4-bit substitution (16-element S-box)
	 *   2. Prime S-box substitution (fixed, number-theoretic)
	 *        Composed with step 1: effective NL ≈ 94, DP_max ≈ 2^-4.7
	 *   2b. Parity-dependent accumulator XOR + prime multiply (key-masked)
	 *        PRIME_TABLE lookup is XORed with tableKey so the previously
	 *        fixed constant becomes key-dependent.
	 *   3. XOR cascade forward — byte[i] ^= rotL(byte[i-1], rotL)
	 *        Spreads each byte's influence rightward (GF(2)^8).
	 *   3b. Prime-gap swap + S-box XOR feedback (V4 only)
	 *        Long-range byte connections via prime-gap distances.
	 *   4. Parity-dependent group switching + modular addition (key-masked)
	 *        Both PRIME_TABLE lookups XORed with tableKey.
	 *   5. Key-derived pre-rotation + bit permutation
	 *        bitRotKey rotates each byte before BIT_PERM so the effective
	 *        bit shuffle is unique per key (2^3 = 8 possible variants).
	 *   5b. Composite-gap modular addition (key-masked)
	 *        COMPOSITE_GAP_TABLE XORed with tableKey.
	 *   6. XOR cascade backward — byte[i] ^= rotL(byte[i+1], rotR)
	 *        Spreads influence leftward, completing bidirectional avalanche.
	 *
	 * @param  string  $data    Raw byte string (arbitrary binary; empty returns '')
	 * @param  array   $params  Output of expandKey() or deriveParams()
	 * @return string           Diffused byte string (same length as input)
	 *
	 * @phpstan-param PipelineParams $params
	 */
	private static function diffuseBytes(string $data, array $params): string
	{
		if ($data === '') {
			return '';
		}

		$bytes = array_values(unpack('C*', $data));
		$len = count($bytes);
		$rotL = $params['rotL'];
		$rotR = $params['rotR'];
		$rounds = $params['rounds'];
		$sbox = $params['sbox'];
		$secure = $params['secure'];

		// tableKey and bitRotKey are only present in secure-mode v2 params.
		// Legacy and v1 secure params fall back to zero-key (no masking).
		$tableKey  = $params['tableKey']  ?? array_fill(0, 32, 0);
		$bitRotKey = $params['bitRotKey'] ?? 0;

		// V3 params: per-round bitRotKeys, independent tableKeyB (step 5b),
		// independent tableKeyC (step 2b).  Fall back to V1/V2 values when absent.
		$bitRotKeys = $params['bitRotKeys'] ?? null;
		$tableKeyB  = $params['tableKeyB']  ?? $tableKey;
		$tableKeyC  = $params['tableKeyC']  ?? $tableKey;
		// gridN=0 for V1/V2 (grid steps skipped); 4 or 8 for V3.
		$gridN      = $params['gridN']      ?? 0;
		// V4: swapKey for prime-gap swap (null for V1/V2/V3).
		$swapKey    = $params['swapKey']    ?? null;

		// V4 bitwise-optimised LUTs (null for V1/V2/V3 — fallback to original code).
		$fusedSbox = $params['fusedSbox'] ?? null;  // step 1+2 in one lookup
		$sboxRot   = $params['sboxRot']   ?? null;  // cascade: rotL(sbox[b], r) in one lookup

		// V4: precompute all 8 rotation LUTs for use in step 5 and post-layers.
		// rotLuts[r][b] = rotateLeft(b, r) — replaces function call with array access.
		$rotLuts = null;
		$p16Lut  = null;
		if ($fusedSbox !== null) {
			$rotLuts = [];
			for ($r = 0; $r < 8; $r++) {
				$rotLuts[$r] = [];
				for ($b = 0; $b < 256; $b++) {
					$rotLuts[$r][$b] = (($b << $r) | ($b >> (8 - $r))) & 0xFF;
				}
			}
			$rotLuts[0] = range(0, 255); // rotateLeft(b, 0) = b
			$p16Lut = self::getPerm16Lut();
		}

		for ($round = 0; $round < $rounds; $round++) {
			// Step 1+2: S-box substitution.
			// V4: fused lookup (PRIME_SBOX_COMP[sbox[x]]) — one array access per byte.
			// V1/V2/V3: original two-pass (step 1 then step 2 separately).
			// Legacy (key=''): nibble-level 4-bit substitution.
			if ($fusedSbox !== null) {
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $fusedSbox[$bytes[$i]];
				}
			} elseif ($secure) {
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $sbox[$bytes[$i]];
				}
				$primeSbox2 = ($params['vecTable'] ?? null) !== null
					? self::PRIME_SBOX_COMP
					: self::PRIME_SBOX;
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $primeSbox2[$bytes[$i]];
				}
			} else {
				// Legacy (key=''): nibble-level 4-bit substitution + prime S-box
				for ($i = 0; $i < $len; $i++) {
					$hi = ($bytes[$i] >> 4) & 0x0F;
					$lo = $bytes[$i] & 0x0F;
					$bytes[$i] = ($sbox[$hi] << 4) | $sbox[$lo];
				}
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = self::PRIME_SBOX[$bytes[$i]];
				}
			}

			// Step 2b: Parity-dependent accumulator XOR + prime multiply
			// V3: uses tableKeyC (independent from tableKey) so this step's masking
			// is decoupled from steps 4a/4b which share tableKey.
			// V1/V2 fallback: tableKeyC === tableKey (same masking as before).
			for ($i = 0; $i < $len; $i++) {
				$idx2b = ($i * 47 + $round) % self::PRIME_TABLE_SIZE;
				$accKey = $idx2b & 0xFF;
				$pv = self::PRIME_TABLE[$idx2b] ^ $tableKeyC[$idx2b & 0x1F];

				if (($bytes[$i] & 1) === 0) {
					$bytes[$i] ^= self::ODD_PARTIAL_ACC[$accKey];
				} else {
					$bytes[$i] ^= self::EVEN_PARTIAL_ACC[$accKey];
				}
				$bytes[$i] ^= $pv;
				$bytes[$i] = ($bytes[$i] * ($pv | 1)) & 0xFF;
			}

			// Step 3: XOR cascade forward.
			// V4: sboxRot[rot][byte] fuses S-box + rotation into one lookup (was 2 calls).
			//     Inline 4×4 ShiftRows avoids array_slice/array_merge overhead.
			// V3: LFSR_ROT_SEQ[$i % 7], applyGridShiftRows().
			// V1/V2 fallback: fixed rotL, no grid operation, linear cascade.
			if ($sboxRot !== null) {
				// V4 fast path: precomputed sboxRot + LFSR_ROTS
				for ($i = 1; $i < $len; $i++) {
					$bytes[$i] ^= $sboxRot[self::LFSR_ROTS[$i]][$bytes[$i - 1]];
				}
				// Inline 4×4 ShiftRows (direct swaps, no function call)
				if ($gridN === 4) {
					for ($bs = 0; $bs + 15 < $len; $bs += 16) {
						// Row 1: cyclic left shift by 1
						$t = $bytes[$bs + 4];
						$bytes[$bs + 4] = $bytes[$bs + 5]; $bytes[$bs + 5] = $bytes[$bs + 6];
						$bytes[$bs + 6] = $bytes[$bs + 7]; $bytes[$bs + 7] = $t;
						// Row 2: cyclic left shift by 2 (two swaps)
						$t = $bytes[$bs + 8]; $bytes[$bs + 8] = $bytes[$bs + 10]; $bytes[$bs + 10] = $t;
						$t = $bytes[$bs + 9]; $bytes[$bs + 9] = $bytes[$bs + 11]; $bytes[$bs + 11] = $t;
						// Row 3: cyclic left shift by 3 (= right shift by 1)
						$t = $bytes[$bs + 15];
						$bytes[$bs + 15] = $bytes[$bs + 14]; $bytes[$bs + 14] = $bytes[$bs + 13];
						$bytes[$bs + 13] = $bytes[$bs + 12]; $bytes[$bs + 12] = $t;
					}
				} elseif ($gridN > 0) {
					$bytes = self::applyGridShiftRows($bytes, $len, $gridN);
				}
			} elseif ($gridN > 0) {
				for ($i = 1; $i < $len; $i++) {
					$feedback = $sbox[$bytes[$i - 1]];
					$bytes[$i] ^= self::rotateLeft($feedback, self::LFSR_ROT_SEQ[$i % 7]);
				}
				$bytes = self::applyGridShiftRows($bytes, $len, $gridN);
			} else {
				for ($i = 1; $i < $len; $i++) {
					$bytes[$i] ^= self::rotateLeft($bytes[$i - 1], $rotL);
				}
			}

			// Step 3b (V4): Prime-gap swap with S-box XOR feedback.
			// Creates long-range byte connections that cascade alone cannot
			// provide, stabilising worst-case avalanche at low round counts.
			// Key-masked swap distances make the pattern unpredictable.
			// Null swapKey (V1/V2/V3) skips this step entirely.
			if ($swapKey !== null) {
				$bytes = self::applyPrimeGapSwap($bytes, $len, $sbox, $round, $swapKey);
			}

			// Step 4: Parity-dependent group switching + modular addition
			// Both PRIME_TABLE lookups masked with tableKey (independent offsets
			// into the 32-byte keystream keep the two sub-steps decorrelated).
			for ($i = 0; $i < $len; $i++) {
				$idx = ($i * 47 + $round) % self::PRIME_TABLE_SIZE;
				$pc  = (self::PRIME_TABLE[$idx] ^ $tableKey[$idx & 0x1F]) | 1;

				// 4a: parity-dependent group switching
				if (($bytes[$i] & 1) === 0) {
					$bytes[$i] = ($bytes[$i] + $pc) & 0xFF;  // even → Z/256Z add → odd
				} else {
					$bytes[$i] = $bytes[$i] ^ $pc;            // odd  → GF(2)^8 xor → even
				}

				// 4b: modular addition (offset +4796 into prime table, +16 into tableKey)
				$bytes[$i] = ($bytes[$i] + (self::PRIME_TABLE[($idx + 4796) % self::PRIME_TABLE_SIZE] ^ $tableKey[($idx + 16) & 0x1F])) & 0xFF;
			}

			// Step 5: bit permutation with pre-rotation.
			// V4: 65536-entry PERM16_LUT replaces permuteWordPair's 16-bit loop
			//     with a single table lookup.  rotLuts pre-rotation avoids function
			//     calls.  Combined: rotate+pack+permute = 3 array accesses per pair.
			// V3: permuteWordPair (per-bit loop, 2 function calls per pair).
			// V1/V2 fallback: single-byte permuteByte.
			$roundBitRotKey = ($bitRotKeys !== null) ? $bitRotKeys[$round % 5] : $bitRotKey;
			if ($p16Lut !== null && $bitRotKeys !== null) {
				// V4 fast path: LUT rotation + LUT 16-bit permutation
				$rl = $rotLuts[$roundBitRotKey];
				$pairEnd = $len - ($len % 2);
				for ($i = 0; $i < $pairEnd; $i += 2) {
					$word = ($rl[$bytes[$i + 1]] << 8) | $rl[$bytes[$i]];
					$pw = $p16Lut[$word];
					$bytes[$i]     = $pw & 0xFF;
					$bytes[$i + 1] = ($pw >> 8) & 0xFF;
				}
				if ($len % 2 === 1) {
					$bytes[$len - 1] = self::PERM_LUT[$rl[$bytes[$len - 1]]];
				}
			} elseif ($bitRotKeys !== null) {
				$pairEnd = $len - ($len % 2);
				for ($i = 0; $i < $pairEnd; $i += 2) {
					$preA = self::rotateLeft($bytes[$i],     $roundBitRotKey);
					$preB = self::rotateLeft($bytes[$i + 1], $roundBitRotKey);
					[$bytes[$i], $bytes[$i + 1]] = self::permuteWordPair($preA, $preB);
				}
				if ($len % 2 === 1) {
					$pre = self::rotateLeft($bytes[$len - 1], $roundBitRotKey);
					$bytes[$len - 1] = self::permuteByte($pre);
				}
			} else {
				for ($i = 0; $i < $len; $i++) {
					$pre = self::rotateLeft($bytes[$i], $roundBitRotKey);
					$bytes[$i] = self::permuteByte($pre);
				}
			}

			// Step 5a (P3): AES-style MixColumns on 4-byte groups.
			// Multiplies each 4-byte column by the MDS matrix [2,3,1,1;1,2,3,1;…]
			// in GF(2^8) with irreducible polynomial x^8+x^4+x^3+x+1.
			// Branch number = 5: any 1-byte input change guarantees ≥4 output bytes
			// change, providing optimal intra-column diffusion.
			// Only applied in V4 secure mode (vecTable present as V4 indicator);
			// V1/V2/V3 paths are unaffected.
			if (($params['vecTable'] ?? null) !== null) {
				for ($i = 0; $i + 3 < $len; $i += 4) {
					$a = $bytes[$i]; $b = $bytes[$i + 1]; $c = $bytes[$i + 2]; $d = $bytes[$i + 3];
					$bytes[$i]     = self::GF_MUL2[$a] ^ self::GF_MUL3[$b] ^ $c              ^ $d;
					$bytes[$i + 1] = $a              ^ self::GF_MUL2[$b] ^ self::GF_MUL3[$c] ^ $d;
					$bytes[$i + 2] = $a              ^ $b              ^ self::GF_MUL2[$c] ^ self::GF_MUL3[$d];
					$bytes[$i + 3] = self::GF_MUL3[$a] ^ $b              ^ $c              ^ self::GF_MUL2[$d];
				}
			}

			// Step 5b: Composite-gap modular addition.
			// V3: uses tableKeyB (independent from tableKey / tableKeyC) so this
			//     step's masking is fully decorrelated from all other steps.
			// V1/V2 fallback: tableKeyB === tableKey (same masking as before).
			for ($i = 0; $i < $len; $i++) {
				$bytes[$i] = ($bytes[$i] + (self::COMPOSITE_GAP_TABLE[($i * 47 + $round) % self::PRIME_TABLE_SIZE] ^ $tableKeyB[($i + $round) & 0x1F])) & 0xFF;
			}

			// Step 6: XOR cascade backward.
			// V4: sboxRot LUT (same as step 3, iterating right-to-left).
			// V3: LFSR_ROT_SEQ[$i % 7], sbox + rotateLeft function calls.
			// V1/V2 fallback: fixed rotR, linear cascade.
			if ($sboxRot !== null) {
				for ($i = $len - 2; $i >= 0; $i--) {
					$bytes[$i] ^= $sboxRot[self::LFSR_ROTS[$i]][$bytes[$i + 1]];
				}
			} elseif ($gridN > 0) {
				for ($i = $len - 2; $i >= 0; $i--) {
					$feedback = $sbox[$bytes[$i + 1]];
					$bytes[$i] ^= self::rotateLeft($feedback, self::LFSR_ROT_SEQ[$i % 7]);
				}
			} else {
				for ($i = $len - 2; $i >= 0; $i--) {
					$bytes[$i] ^= self::rotateLeft($bytes[$i + 1], $rotR);
				}
			}
		}

		// V4 post-diffusion: key-masked π⊕e⊕primes vector shift+XOR layer.
		// V4 optimised: uses rotLuts instead of rotateLeft function calls.
		// vecTable is null for V1/V2/V3 — those paths are unaffected.
		$vecTable = $params['vecTable'] ?? null;
		if ($vecTable !== null) {
			if ($rotLuts !== null) {
				// V4 fast path: inline vecTable + P6 sbox + primeShift
				$prev = 0;
				for ($i = 0; $i < $len; $i++) {
					$v = $vecTable[$i & 0xFF];
					$shifted = $rotLuts[$v & 0x07][$bytes[$i]];
					$bytes[$i] = ($shifted ^ $v ^ $rotLuts[($v >> 3) & 0x07][$prev]) & 0xFF;
					$prev = $bytes[$i];
				}
			} else {
				$bytes = self::applyVectorShiftXor($bytes, $vecTable);
			}

			// P6: S-box whitening between vecTable and primeShift layers.
			// Inserts a nonlinear boundary between two otherwise-linear post-diffusion
			// transforms, preventing an attacker from combining them into a single
			// affine relation over GF(2)^8.
			for ($i = 0; $i < $len; $i++) {
				$bytes[$i] = $sbox[$bytes[$i]];
			}
		}

		// V4 n+n prime shift+XOR layer.
		// V4 optimised: inline rotation via rotLuts.
		// primeShiftKey is null for V1/V2/V3.
		$primeShiftKey = $params['primeShiftKey'] ?? null;
		if ($primeShiftKey !== null) {
			if ($rotLuts !== null) {
				for ($i = 0; $i < $len; $i++) {
					$v = (self::PRIME_GAP_PI_TABLE[$i & 0xFF] ^ $primeShiftKey[$i & 0x1F]) & 0xFF;
					$bytes[$i] = ($rotLuts[$v & 0x07][$bytes[$i]] ^ $v) & 0xFF;
				}
			} else {
				$bytes = self::applyPrimeShiftXor($bytes, $len, $primeShiftKey);
			}
		}

		return pack('C*', ...$bytes);
	}

	/**
	 * Reverse the diffusion applied by diffuseBytes().
	 * Steps are applied in reverse order (6→1), from last round to first.
	 *
	 * @param  string $data    Diffused byte string (must match length from encryption)
	 * @param  array  $params  Must be identical to the params used during encryption
	 * @return string          Original byte string (same length as input)
	 *
	 * @phpstan-param PipelineParams $params
	 */
	private static function undiffuseBytes(string $data, array $params): string
	{
		if ($data === '') {
			return '';
		}

		$bytes = array_values(unpack('C*', $data));
		$len = count($bytes);
		$rotL = $params['rotL'];
		$rotR = $params['rotR'];
		$rounds = $params['rounds'];
		$sboxInv = $params['sboxInv'];
		$sbox    = $params['sbox'];
		$secure = $params['secure'];

		$tableKey  = $params['tableKey']  ?? array_fill(0, 32, 0);
		$bitRotKey = $params['bitRotKey'] ?? 0;

		$bitRotKeys = $params['bitRotKeys'] ?? null;
		$tableKeyB  = $params['tableKeyB']  ?? $tableKey;
		$tableKeyC  = $params['tableKeyC']  ?? $tableKey;
		$gridN      = $params['gridN']      ?? 0;
		$swapKey    = $params['swapKey']    ?? null;

		// V4 bitwise-optimised LUTs (null for V1/V2/V3).
		$fusedSboxInv = $params['fusedSboxInv'] ?? null;
		$sboxRot      = $params['sboxRot']      ?? null;

		// Build rotation LUTs and inverse 16-bit perm LUT for V4 fast path.
		$rotLuts  = null;
		$unP16Lut = null;
		if ($fusedSboxInv !== null) {
			$rotLuts = [];
			for ($r = 0; $r < 8; $r++) {
				$rotLuts[$r] = [];
				for ($b = 0; $b < 256; $b++) {
					$rotLuts[$r][$b] = (($b << $r) | ($b >> (8 - $r))) & 0xFF;
				}
			}
			$rotLuts[0] = range(0, 255);
			$unP16Lut = self::getUnPerm16Lut();
		}

		// V4 pre-undiffusion: undo post-layers (applied last during encryption).
		$vecTable = $params['vecTable'] ?? null;
		if ($vecTable !== null) {
			// Undo primeShift first (it was applied last).
			$primeShiftKey = $params['primeShiftKey'] ?? null;
			if ($primeShiftKey !== null) {
				if ($rotLuts !== null) {
					for ($i = 0; $i < $len; $i++) {
						$v = (self::PRIME_GAP_PI_TABLE[$i & 0xFF] ^ $primeShiftKey[$i & 0x1F]) & 0xFF;
						$shift = $v & 0x07;
						$unXored = ($bytes[$i] ^ $v) & 0xFF;
						$bytes[$i] = $rotLuts[(8 - $shift) & 0x07][$unXored];
					}
				} else {
					$bytes = self::reversePrimeShiftXor($bytes, $len, $primeShiftKey);
				}
			}

			// P6 inverse: undo S-box whitening.
			for ($i = 0; $i < $len; $i++) {
				$bytes[$i] = $sboxInv[$bytes[$i]];
			}

			// Undo vecTable.
			if ($rotLuts !== null) {
				$prev = 0;
				for ($i = 0; $i < $len; $i++) {
					$v      = $vecTable[$i & 0xFF];
					$xored  = ($bytes[$i] ^ $v ^ $rotLuts[($v >> 3) & 0x07][$prev]) & 0xFF;
					$prev   = $bytes[$i];
					$bytes[$i] = $rotLuts[(8 - ($v & 0x07)) & 0x07][$xored];
				}
			} else {
				$bytes = self::reverseVectorShiftXor($bytes, $vecTable);
			}
		}

		for ($round = $rounds - 1; $round >= 0; $round--) {
			// Reverse step 6: undo backward XOR cascade.
			// V4: sboxRot LUT, left-to-right iteration (mirror of encryption's right-to-left).
			if ($sboxRot !== null) {
				for ($i = 0; $i < $len - 1; $i++) {
					$bytes[$i] ^= $sboxRot[self::LFSR_ROTS[$i]][$bytes[$i + 1]];
				}
			} elseif ($gridN > 0) {
				for ($i = 0; $i < $len - 1; $i++) {
					$feedback = $sbox[$bytes[$i + 1]];
					$bytes[$i] ^= self::rotateLeft($feedback, self::LFSR_ROT_SEQ[$i % 7]);
				}
			} else {
				for ($i = 0; $i < $len - 1; $i++) {
					$bytes[$i] ^= self::rotateLeft($bytes[$i + 1], $rotR);
				}
			}

			// Reverse step 5b: undo composite-gap modular addition.
			for ($i = 0; $i < $len; $i++) {
				$bytes[$i] = ($bytes[$i] - (self::COMPOSITE_GAP_TABLE[($i * 47 + $round) % self::PRIME_TABLE_SIZE] ^ $tableKeyB[($i + $round) & 0x1F]) + 256) & 0xFF;
			}

			// Reverse step 5a (P3): Inverse MixColumns.
			if (($params['vecTable'] ?? null) !== null) {
				for ($i = 0; $i + 3 < $len; $i += 4) {
					$a = $bytes[$i]; $b = $bytes[$i + 1]; $c = $bytes[$i + 2]; $d = $bytes[$i + 3];
					$bytes[$i]     = self::GF_MUL14[$a] ^ self::GF_MUL11[$b] ^ self::GF_MUL13[$c] ^ self::GF_MUL9[$d];
					$bytes[$i + 1] = self::GF_MUL9[$a]  ^ self::GF_MUL14[$b] ^ self::GF_MUL11[$c] ^ self::GF_MUL13[$d];
					$bytes[$i + 2] = self::GF_MUL13[$a] ^ self::GF_MUL9[$b]  ^ self::GF_MUL14[$c] ^ self::GF_MUL11[$d];
					$bytes[$i + 3] = self::GF_MUL11[$a] ^ self::GF_MUL13[$b] ^ self::GF_MUL9[$c]  ^ self::GF_MUL14[$d];
				}
			}

			// Reverse step 5: undo bit permutation + pre-rotation.
			// V4: 65536-entry inverse PERM16 LUT + rotLuts for inverse rotation.
			$roundBitRotKey = ($bitRotKeys !== null) ? $bitRotKeys[$round % 5] : $bitRotKey;
			if ($unP16Lut !== null && $bitRotKeys !== null) {
				$invRl = $rotLuts[(8 - $roundBitRotKey) & 0x07];
				if ($len % 2 === 1) {
					$bytes[$len - 1] = $invRl[self::PERM_INV_LUT[$bytes[$len - 1]]];
				}
				$pairEnd = $len - ($len % 2);
				for ($i = 0; $i < $pairEnd; $i += 2) {
					$word = ($bytes[$i + 1] << 8) | $bytes[$i];
					$uw = $unP16Lut[$word];
					$bytes[$i]     = $invRl[$uw & 0xFF];
					$bytes[$i + 1] = $invRl[($uw >> 8) & 0xFF];
				}
			} elseif ($bitRotKeys !== null) {
				if ($len % 2 === 1) {
					$unpermuted = self::unPermuteByte($bytes[$len - 1]);
					$bytes[$len - 1] = self::rotateLeft($unpermuted, 8 - $roundBitRotKey);
				}
				$pairEnd = $len - ($len % 2);
				for ($i = 0; $i < $pairEnd; $i += 2) {
					[$uA, $uB] = self::unPermuteWordPair($bytes[$i], $bytes[$i + 1]);
					$bytes[$i]     = self::rotateLeft($uA, 8 - $roundBitRotKey);
					$bytes[$i + 1] = self::rotateLeft($uB, 8 - $roundBitRotKey);
				}
			} else {
				for ($i = 0; $i < $len; $i++) {
					$unpermuted = self::unPermuteByte($bytes[$i]);
					$bytes[$i] = self::rotateLeft($unpermuted, 8 - $bitRotKey);
				}
			}

			// Reverse step 4: undo modular addition, then undo parity mix.
			for ($i = 0; $i < $len; $i++) {
				$idx = ($i * 47 + $round) % self::PRIME_TABLE_SIZE;
				$pc  = (self::PRIME_TABLE[$idx] ^ $tableKey[$idx & 0x1F]) | 1;

				$bytes[$i] = ($bytes[$i] - (self::PRIME_TABLE[($idx + 4796) % self::PRIME_TABLE_SIZE] ^ $tableKey[($idx + 16) & 0x1F]) + 256) & 0xFF;

				if (($bytes[$i] & 1) === 1) {
					$bytes[$i] = ($bytes[$i] - $pc + 256) & 0xFF;
				} else {
					$bytes[$i] = $bytes[$i] ^ $pc;
				}
			}

			// Reverse step 3b (V4): undo prime-gap swap.
			if ($swapKey !== null) {
				$bytes = self::reversePrimeGapSwap($bytes, $len, $sbox, $round, $swapKey);
			}

			// Reverse step 3: undo grid ShiftRows then undo forward cascade.
			// V4: inline 4×4 reverse ShiftRows + sboxRot LUT cascade.
			if ($sboxRot !== null) {
				// Inline reverse 4×4 ShiftRows (right-shift each row by row index)
				if ($gridN === 4) {
					for ($bs = 0; $bs + 15 < $len; $bs += 16) {
						// Row 1: cyclic right shift by 1
						$t = $bytes[$bs + 7];
						$bytes[$bs + 7] = $bytes[$bs + 6]; $bytes[$bs + 6] = $bytes[$bs + 5];
						$bytes[$bs + 5] = $bytes[$bs + 4]; $bytes[$bs + 4] = $t;
						// Row 2: cyclic right shift by 2 (same as left by 2)
						$t = $bytes[$bs + 8]; $bytes[$bs + 8] = $bytes[$bs + 10]; $bytes[$bs + 10] = $t;
						$t = $bytes[$bs + 9]; $bytes[$bs + 9] = $bytes[$bs + 11]; $bytes[$bs + 11] = $t;
						// Row 3: cyclic right shift by 3 (= left shift by 1)
						$t = $bytes[$bs + 12];
						$bytes[$bs + 12] = $bytes[$bs + 13]; $bytes[$bs + 13] = $bytes[$bs + 14];
						$bytes[$bs + 14] = $bytes[$bs + 15]; $bytes[$bs + 15] = $t;
					}
				} elseif ($gridN > 0) {
					$bytes = self::reverseGridShiftRows($bytes, $len, $gridN);
				}
				// Undo forward cascade with sboxRot LUT
				for ($i = $len - 1; $i >= 1; $i--) {
					$bytes[$i] ^= $sboxRot[self::LFSR_ROTS[$i]][$bytes[$i - 1]];
				}
			} elseif ($gridN > 0) {
				$bytes = self::reverseGridShiftRows($bytes, $len, $gridN);
				for ($i = $len - 1; $i >= 1; $i--) {
					$feedback = $sbox[$bytes[$i - 1]];
					$bytes[$i] ^= self::rotateLeft($feedback, self::LFSR_ROT_SEQ[$i % 7]);
				}
			} else {
				for ($i = $len - 1; $i >= 1; $i--) {
					$bytes[$i] ^= self::rotateLeft($bytes[$i - 1], $rotL);
				}
			}

			// Reverse step 2b: undo parity accumulator XOR + prime multiply.
			for ($i = 0; $i < $len; $i++) {
				$idx2b = ($i * 47 + $round) % self::PRIME_TABLE_SIZE;
				$accKey = $idx2b & 0xFF;
				$pv = self::PRIME_TABLE[$idx2b] ^ $tableKeyC[$idx2b & 0x1F];
				$pMul = $pv | 1;

				$bytes[$i] = ($bytes[$i] * self::MOD_INV_256[$pMul]) & 0xFF;
				$bytes[$i] ^= $pv;
				if (($bytes[$i] & 1) === 0) {
					$bytes[$i] ^= self::ODD_PARTIAL_ACC[$accKey];
				} else {
					$bytes[$i] ^= self::EVEN_PARTIAL_ACC[$accKey];
				}
			}

			// Reverse step 2+1: inverse S-box.
			// V4: fused inverse lookup (single pass).
			if ($fusedSboxInv !== null) {
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $fusedSboxInv[$bytes[$i]];
				}
			} elseif ($secure) {
				$primeSboxInv2 = ($params['vecTable'] ?? null) !== null
					? self::PRIME_SBOX_COMP_INV
					: self::PRIME_SBOX_INV;
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $primeSboxInv2[$bytes[$i]];
				}
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = $sboxInv[$bytes[$i]];
				}
			} else {
				for ($i = 0; $i < $len; $i++) {
					$bytes[$i] = self::PRIME_SBOX_INV[$bytes[$i]];
				}
				for ($i = 0; $i < $len; $i++) {
					$hi = ($bytes[$i] >> 4) & 0x0F;
					$lo = $bytes[$i] & 0x0F;
					$bytes[$i] = ($sboxInv[$hi] << 4) | $sboxInv[$lo];
				}
			}
		}

		return pack('C*', ...$bytes);
	}

	// ═══════════════════════════════════════════════════════════════════
	// ARBITRARY-PRECISION DECIMAL ARITHMETIC (pure PHP, no GMP/bcmath)
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Multiply a non-negative decimal string by a single digit (0–9).
	 *
	 * This implements grade-school long multiplication on a string-encoded
	 * arbitrary-precision integer. Used for decimal ↔ octal base conversion.
	 *
	 * @internal Part of the pure-PHP big-integer arithmetic layer.
	 *
	 * @param  string $number      Non-negative decimal string (no leading zeros except "0")
	 * @param  int    $multiplier  Single digit multiplier (0–9)
	 * @return string              Product as a decimal string
	 */
	private static function bigMulSmall(string $number, int $multiplier): string
	{
		if ($multiplier === 0 || $number === '0') {
			return '0';
		}
		if ($multiplier === 1) {
			return $number;
		}

		$carry = 0;
		$length = strlen($number);
		$result = '';

		for ($i = $length - 1; $i >= 0; $i--) {
			$product = (int) $number[$i] * $multiplier + $carry;
			$carry = intdiv($product, 10);
			$result = ($product % 10) . $result;
		}

		return $carry > 0 ? $carry . $result : $result;
	}

	/**
	 * Add a single digit (0–9) to a non-negative decimal string.
	 *
	 * Performs ripple-carry addition from least-significant digit upward,
	 * early-exiting once the carry is exhausted.
	 *
	 * @internal Part of the pure-PHP big-integer arithmetic layer.
	 *
	 * @param  string $number  Non-negative decimal string
	 * @param  int    $addend  Single digit addend (0–9)
	 * @return string          Sum as a decimal string
	 */
	private static function bigAddSmall(string $number, int $addend): string
	{
		if ($addend === 0) {
			return $number;
		}

		$carry = $addend;
		$length = strlen($number);
		$result = '';
		$i = $length - 1;

		for (; $i >= 0 && $carry > 0; $i--) {
			$sum = (int) $number[$i] + $carry;
			$carry = intdiv($sum, 10);
			$result = ($sum % 10) . $result;
		}

		if ($i >= 0) {
			$result = substr($number, 0, $i + 1) . $result;
		}

		return $carry > 0 ? $carry . $result : $result;
	}

	/**
	 * Divide a non-negative decimal string by a small integer.
	 *
	 * Performs grade-school long division from most-significant digit downward.
	 *
	 * @internal Part of the pure-PHP big-integer arithmetic layer.
	 *
	 * @param  string $number   Non-negative decimal string
	 * @param  int    $divisor  Positive divisor (must be > 0)
	 * @return array{0: string, 1: int}  [quotient, remainder]
	 *
	 * @throws InvalidArgumentException If divisor is zero
	 */
	private static function bigDivModSmall(string $number, int $divisor): array
	{
		if ($divisor <= 0) {
			throw new InvalidArgumentException("Divisor must be positive, got {$divisor}");
		}

		$length = strlen($number);
		$quotient = '';
		$remainder = 0;

		for ($i = 0; $i < $length; $i++) {
			$current = $remainder * 10 + (int) $number[$i];
			$quotient .= intdiv($current, $divisor);
			$remainder = $current % $divisor;
		}

		$quotient = ltrim($quotient, '0');
		return [$quotient === '' ? '0' : $quotient, $remainder];
	}

	// ═══════════════════════════════════════════════════════════════════
	// ENCODING HELPERS
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Convert a hex string to its binary (base-2) string representation.
	 *
	 * Each hex digit is expanded to 4 binary digits using a lookup table.
	 * Leading zeros are stripped; returns '0' for an all-zero input.
	 *
	 * @param  string $hex  Hexadecimal string (case-insensitive; empty returns '')
	 * @return string       Binary digit string (e.g. 'ff' → '11111111')
	 */
	public static function hexToBin(string $hex): string
	{
		if ($hex === '') {
			return '';
		}

		$binary = '';
		foreach (str_split(strtolower($hex)) as $c) {
			$binary .= self::HEX_TO_BIN_MAP[$c];
		}

		$binary = ltrim($binary, '0');
		return $binary === '' ? '0' : $binary;
	}

	/**
	 * Convert a binary (base-2) string to its hex representation.
	 *
	 * Pads to a multiple of 4 bits before conversion; strips leading hex zeros.
	 *
	 * @param  string $binary  Binary digit string ('0'/'1' characters; empty returns '')
	 * @return string          Hexadecimal string (lowercase; e.g. '11111111' → 'ff')
	 */
	public static function binToHex(string $binary): string
	{
		if ($binary === '') {
			return '';
		}

		$padLen = (4 - (strlen($binary) % 4)) % 4;
		$binary = str_repeat('0', $padLen) . $binary;

		$hex = '';
		$length = strlen($binary);
		for ($i = 0; $i < $length; $i += 4) {
			$hex .= self::BIN_TO_HEX_MAP[substr($binary, $i, 4)];
		}

		$hex = ltrim($hex, '0');
		return $hex === '' ? '0' : $hex;
	}

	/**
	 * Convert an octal string to a decimal string using big-integer arithmetic.
	 *
	 * Implements Horner's method: processes digits left-to-right, accumulating
	 * result = result × 8 + digit at each step.
	 *
	 * Complexity: O(n²) where n = strlen($octal), due to string-based multiplication.
	 *
	 * Uses GMP or bcmath when available (both O(n·log n) or better), otherwise
	 * falls back to the pure-PHP Horner's method (O(n²)).
	 *
	 * @param  string $octal  Octal digit string ('0'–'7'; empty returns '')
	 * @return string         Decimal digit string
	 */
	public static function octalToDecimalString(string $octal): string
	{
		if ($octal === '') {
			return '';
		}

		if (extension_loaded('gmp')) {
			// @phpstan-ignore-next-line
			return gmp_strval(gmp_init($octal, 8), 10);
		}

		if (extension_loaded('bcmath')) {
			$result = '0';
			$length = strlen($octal);
			for ($i = 0; $i < $length; $i++) {
				$result = bcadd(bcmul($result, '8'), (string) (int) $octal[$i]);
			}
			return $result;
		}

		// Pure-PHP fallback: Horner's method, O(n²)
		$result = '0';
		$length = strlen($octal);
		for ($i = 0; $i < $length; $i++) {
			$result = self::bigMulSmall($result, 8);
			$result = self::bigAddSmall($result, (int) $octal[$i]);
		}

		return $result;
	}

	/**
	 * Convert a decimal string to an octal string using big-integer arithmetic.
	 *
	 * Repeatedly divides by 8, collecting remainders in reverse order.
	 *
	 * Complexity: O(n²) where n = strlen($decimal), due to string-based division.
	 *
	 * Uses GMP or bcmath when available (both O(n·log n) or better), otherwise
	 * falls back to the pure-PHP repeated-division method (O(n²)).
	 *
	 * @param  string $decimal  Decimal digit string (empty returns ''; '0' returns '0')
	 * @return string           Octal digit string
	 */
	public static function decimalStringToOctal(string $decimal): string
	{
		if ($decimal === '' || $decimal === '0') {
			return $decimal === '' ? '' : '0';
		}

		if (extension_loaded('gmp')) {
			// @phpstan-ignore-next-line
			return gmp_strval(gmp_init($decimal, 10), 8);
		}

		if (extension_loaded('bcmath')) {
			$octal = '';
			while (bccomp($decimal, '0') > 0) {
				$octal   = bcmod($decimal, '8') . $octal;
				$decimal = bcdiv($decimal, '8', 0);
			}
			return $octal === '' ? '0' : $octal;
		}

		// Pure-PHP fallback: repeated division, O(n²)
		$octal = '';
		while ($decimal !== '0') {
			[$decimal, $remainder] = self::bigDivModSmall($decimal, 8);
			$octal = $remainder . $octal;
		}

		return $octal === '' ? '0' : $octal;
	}

	/**
	 * Decode a hex string to a raw byte string, stripping leading zero bytes.
	 *
	 * Returns "\0" if the input is all zeros (preserves the distinction between
	 * empty input and zero-valued input).
	 *
	 * @param  string $hex  Hexadecimal string (case-insensitive; empty returns '')
	 * @return string       Raw binary string
	 */
	public static function fromHex(string $hex): string
	{
		if ($hex === '') {
			return '';
		}

		$cleaned = ltrim($hex, '0');

		if ($cleaned === '') {
			return "\0";
		}

		if (strlen($cleaned) % 2 !== 0) {
			$cleaned = '0' . $cleaned;
		}

		$binary = hex2bin($cleaned);
		return $binary !== false ? $binary : '';
	}

	/**
	 * Encode a UTF-8 string as a zero-padded hex string.
	 *
	 * The output is always at least 40 hex characters (20 bytes), left-padded
	 * with zeros. This ensures a minimum output length for short inputs.
	 *
	 * @param  string $input  Arbitrary binary/UTF-8 string
	 * @return string         Lowercase hex string (minimum 40 characters)
	 */
	public static function toHex(string $input): string
	{
		return str_pad(bin2hex($input), 40, '0', STR_PAD_LEFT);
	}

	/**
	 * Encode a string as uppercase hex (one hex pair per byte).
	 *
	 * Note: Unlike bin2hex(), this outputs uppercase and does NOT zero-pad
	 * individual bytes below 0x10 (e.g. 0x0A → 'A' not '0A'). This is
	 * preserved for backward compatibility.
	 *
	 * @param  string $ascii  Input string (each byte is converted independently)
	 * @return string         Uppercase hex representation
	 */
	public static function asciiToHex(string $ascii): string
	{
		$result = '';
		$length = strlen($ascii);
		for ($i = 0; $i < $length; $i++) {
			$result .= strtoupper(dechex(ord($ascii[$i])));
		}
		return $result;
	}

	/**
	 * Convert a binary (base-2) string to a native integer.
	 *
	 * WARNING: Result is bounded by PHP_INT_MAX. For binary strings longer
	 * than PHP_INT_SIZE × 8 bits, the result will silently overflow.
	 * Use octalToDecimalString() for arbitrary-precision conversion.
	 *
	 * @param  string $binaryString  Binary digit string ('0'/'1' characters)
	 * @return int                   Decoded integer value
	 */
	public static function binaryStringToDecimal(string $binaryString): int
	{
		$decimal = 0;
		$length = strlen($binaryString);
		for ($i = 0; $i < $length; $i++) {
			$decimal = ($decimal << 1) | ($binaryString[$i] === '1' ? 1 : 0);
		}
		return $decimal;
	}

	/**
	 * Count the number of set bits in an integer (Hamming weight / popcount).
	 *
	 * Uses the parallel bit-counting algorithm (Hacker's Delight, Chapter 5).
	 * Valid for 32-bit unsigned integers. For 64-bit systems, only the low
	 * 32 bits are counted.
	 *
	 * @param  int $value  Input integer (only low 32 bits are considered)
	 * @return int         Number of set bits (0–32)
	 */
	public static function getBitCount(int $value): int
	{
		$value = $value - (($value >> 1) & 0x55555555);
		$value = ($value & 0x33333333) + (($value >> 2) & 0x33333333);
		return ((($value + ($value >> 4)) & 0x0F0F0F0F) * 0x01010101) >> 24;
	}

	// ═══════════════════════════════════════════════════════════════════
	// QUEUE (RUN-LENGTH) ENCODING
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Run-length encode a binary string.
	 *
	 * Encoding scheme:
	 *   A run of k ones  emits digit  k           (1 ≤ k ≤ runMax)
	 *   A run of k zeros emits digit  5 + k       (6 ≤ 5+k ≤ 5+runMax ≤ 9)
	 *
	 * The digit '5' is therefore NEVER emitted and is reserved as
	 * PREFIX_SENTINEL for makePrefixForEncrypt().
	 *
	 * @param  string $bitString  Binary string of '0'/'1' characters
	 * @param  int    $runMax     Maximum run length before forced flush (1–4)
	 * @return string             Run-length encoded digit string
	 */
	protected static function queueEncrypt(string $bitString, int $runMax = self::DEFAULT_RUN_MAX): string
	{
		if ($bitString === '') {
			return '';
		}

		$out = '';
		$length = strlen($bitString);
		$currentBit = -1;
		$runLength = 0;

		for ($i = 0; $i <= $length; $i++) {
			$bit = ($i === $length) ? -1 : (int) $bitString[$i];

			if ($currentBit === -1) {
				$currentBit = $bit;
				$runLength = 1;
			} elseif ($i === $length || $bit !== $currentBit || $runLength >= $runMax) {
				$out .= ($currentBit === 0) ? (string) (5 + $runLength) : (string) $runLength;
				$runLength = 1;
				$currentBit = ($i === $length) ? -1 : $bit;
			} else {
				$runLength++;
			}
		}

		return $out;
	}

	/**
	 * Decode a run-length encoded digit string back to a binary string.
	 *
	 * Decoding scheme:
	 *   digit 1–4  → that many '1's
	 *   digit 6–9  → (digit − 5) '0's
	 *   digit 5    → PREFIX_SENTINEL, silently skipped
	 *   digit 0    → ignored (should not appear)
	 *
	 * @param  string $encoded  Run-length encoded digit string
	 * @return string           Binary string of '0'/'1' characters
	 */
	protected static function queueDecrypt(string $encoded): string
	{
		$out = '';
		$length = strlen($encoded);

		for ($i = 0; $i < $length; $i++) {
			$val = (int) $encoded[$i];

			if ($val > 5) {
				$out .= str_repeat('0', $val - 5);
			} elseif ($val > 0 && $val < 5) {
				$out .= str_repeat('1', $val);
			}
			// val === 5: PREFIX_SENTINEL — skip silently
		}

		return $out;
	}

	/**
	 * Dispatch to queueEncrypt() or queueDecrypt() by mode string.
	 *
	 * @param  string $data    Binary string (for Encrypt) or RLE string (for Decrypt)
	 * @param  string $mode    'Encrypt' or 'Decrypt' (case-sensitive)
	 * @param  int    $runMax  Maximum run length (only used in Encrypt mode; 1–4)
	 * @return string          Encoded or decoded string; returns $data unchanged for invalid mode
	 *
	 * @deprecated Prefer calling queueEncrypt()/queueDecrypt() directly.
	 *             This dispatcher is retained for backward compatibility.
	 */
	public static function queue(string $data, string $mode, int $runMax = self::DEFAULT_RUN_MAX): string
	{
		if ($mode === 'Encrypt') {
			return self::queueEncrypt($data, $runMax);
		}
		if ($mode === 'Decrypt') {
			return self::queueDecrypt($data);
		}
		return $data;
	}

	// ═══════════════════════════════════════════════════════════════════
	// PREFIX COMPRESSION
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Apply prefix compression before the decimal → octal conversion.
	 *
	 * When the first and last characters of the run-length string are equal,
	 * we can save one character by encoding:
	 *   [ a, b, c, d, e, a ]  →  [ SENTINEL, a, b, c, d, e ]
	 *
	 * Why SENTINEL = '5' (not '0'):
	 *   The octal conversion treats the string as a large integer.
	 *   A leading '0' is numerically identical to no prefix (it is dropped).
	 *   '5' is never produced by queueEncrypt and, as the leading digit of a
	 *   non-zero integer (5xxx…), survives the round-trip unchanged.
	 *
	 * @param  string $bitString  Run-length encoded digit string
	 * @return string             Compressed string
	 */
	protected static function makePrefixForEncrypt(string $bitString): string
	{
		$len = strlen($bitString);

		if ($len <= 1) {
			return $bitString;
		}

		if ($bitString[0] === $bitString[$len - 1]) {
			return self::PREFIX_SENTINEL . $bitString[0] . substr($bitString, 1, $len - 2);
		}

		return $bitString;
	}

	/**
	 * Reverse the prefix compression applied by makePrefixForEncrypt().
	 *
	 *   [ SENTINEL, a, b, c, d, e ]  →  [ a, b, c, d, e, a ]
	 *
	 * @param  string $bitString  Run-length string (possibly prefix-compressed)
	 * @return string             Restored run-length string
	 */
	protected static function makePrefixForDecrypt(string $bitString): string
	{
		$len = strlen($bitString);

		if ($len <= 2) {
			return $bitString;
		}

		if ($bitString[0] === self::PREFIX_SENTINEL) {
			$carry = $bitString[1];
			return $carry . substr($bitString, 2) . $carry;
		}

		return $bitString;
	}

	/**
	 * Dispatch to makePrefixForEncrypt() or makePrefixForDecrypt() by mode.
	 *
	 * @param  string $bitString  RLE digit string
	 * @param  string $mode       'Encrypt' or 'Decrypt' (case-sensitive)
	 * @return string             Processed string; returns $bitString unchanged for invalid mode
	 *
	 * @deprecated Prefer calling makePrefixForEncrypt()/makePrefixForDecrypt() directly.
	 *             This dispatcher is retained for backward compatibility.
	 */
	public static function makePrefix(string $bitString, string $mode): string
	{
		if ($mode === 'Encrypt') {
			return self::makePrefixForEncrypt($bitString);
		}
		if ($mode === 'Decrypt') {
			return self::makePrefixForDecrypt($bitString);
		}
		return $bitString;
	}

	/**
	 * Swap selected bit pairs in the middle of a binary string.
	 * Odd-indexed positions in the first half are swapped with the last character.
	 *
	 * @deprecated This function is not used in the encryption/decryption pipeline
	 *             and has no inverse operation. Retained for backward compatibility only.
	 */
	public static function intersect(string $bitString): string
	{
		$len = strlen($bitString);
		if ($len < 2) {
			return $bitString;
		}

		$half = intdiv($len, 2);
		$chars = str_split($bitString);

		for ($i = 0; $i < $half; $i++) {
			if ($i % 2 === 1) {
				[$chars[$i], $chars[$len - 1]] = [$chars[$len - 1], $chars[$i]];
			}
		}

		return implode('', $chars);
	}

	// ═══════════════════════════════════════════════════════════════════
	// CORE PIPELINE (shared by encrypt and decrypt)
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Run the full encryption pipeline and return the octal string.
	 *
	 * Pipeline: plaintext → diffuse → 0xFF sentinel + hex → binary
	 *           → run-length encode → prefix compress → decimal → octal
	 *
	 * The 0xFF sentinel ensures that the hex representation always starts
	 * with 'ff', preventing leading-zero loss during numeric base conversions.
	 *
	 * @param  string $plainText  Raw plaintext bytes
	 * @param  array  $params     Output of expandKey() or deriveParams()
	 * @return string             Octal-encoded ciphertext (before base64 wrapping)
	 *
	 * @phpstan-param PipelineParams $params
	 */
	private static function runEncryptPipeline(string $plainText, array $params): string
	{
		// Prepend 0xFF sentinel so the hex string always starts with 'ff',
		// preventing leading-zero loss in the subsequent numeric conversions.
		$diffused = self::diffuseBytes($plainText, $params);
		$hex = 'ff' . bin2hex($diffused);
		$binary = self::hexToBin($hex);

		$queued = self::queueEncrypt($binary, $params['runMax']);
		$queued = self::makePrefixForEncrypt($queued);

		return self::decimalStringToOctal($queued);
	}

	/**
	 * Run the full decryption pipeline and return the plaintext.
	 *
	 * Pipeline: octal → decimal → prefix restore → run-length decode → binary → hex
	 *           → strip 0xFF sentinel → undiffuse → plaintext
	 *
	 * This is the exact inverse of runEncryptPipeline().
	 *
	 * @param  string $octal   Octal-encoded ciphertext (raw octal digits, not base64)
	 * @param  array  $params  Must exactly match the params used during encryption
	 * @return string          Decrypted plaintext bytes
	 *
	 * @phpstan-param PipelineParams $params
	 */
	private static function runDecryptPipeline(string $octal, array $params): string
	{
		$decimal = self::octalToDecimalString($octal);
		$decimal = self::makePrefixForDecrypt($decimal);
		$queued = self::queueDecrypt($decimal);
		$hex = self::binToHex($queued);
		$rawBytes = self::fromHex($hex);

		// Strip the 0xFF sentinel prepended during encryption
		$diffused = substr($rawBytes, 1);

		return self::undiffuseBytes($diffused, $params);
	}

	/**
	 * Pack an RLE digit string into a nibble-compressed byte string.
	 *
	 * RLE digits are in {1..4, 5, 6..9} — all fit in a 4-bit nibble.
	 * Two digits are packed per byte via bitwise operations:
	 *   byte = (digit_even << 4) | digit_odd
	 *
	 * Wire format:
	 *   pack('n', count) | nibble_bytes
	 *   where count is the number of RLE digits (≤ 65535, 2-byte big-endian).
	 *
	 * This replaces the O(n²) decimal → octal big-integer stage with O(n)
	 * bit manipulation, halving storage relative to ASCII-digit representation.
	 *
	 * @param  string $rle  RLE digit string (digits 1–9)
	 * @return string       Nibble-packed byte string (2-byte length header + data)
	 */
	private static function packRleToNibbles(string $rle): string
	{
		$len = strlen($rle);
		$result = pack('N', $len);

		for ($i = 0; $i < $len; $i += 2) {
			$hi = (int) $rle[$i];
			$lo = ($i + 1 < $len) ? (int) $rle[$i + 1] : 0;
			$result .= chr(($hi << 4) | $lo);
		}

		return $result;
	}

	/**
	 * Unpack a nibble-compressed byte string back to an RLE digit string.
	 * Exact inverse of packRleToNibbles().
	 *
	 * @param  string $packed  Nibble-packed byte string (2-byte length header + data)
	 * @return string          RLE digit string (digits 1–9)
	 */
	private static function unpackNibblesToRle(string $packed): string
	{
		if (strlen($packed) < 4) {
			return '';
		}

		$len    = unpack('N', substr($packed, 0, 4))[1];
		$result = '';
		$data   = substr($packed, 4);
		$bytes  = strlen($data);

		for ($i = 0; $i < $bytes && strlen($result) < $len; $i++) {
			$byte = ord($data[$i]);
			$result .= (string) (($byte >> 4) & 0x0F);
			if (strlen($result) < $len) {
				$result .= (string) ($byte & 0x0F);
			}
		}

		return $result;
	}

	/**
	 * V4 encryption pipeline — compact nibble-packed encoding.
	 *
	 * Replaces the decimal→octal big-integer stage with packRleToNibbles(),
	 * reducing encoding overhead to ~4/3× and eliminating O(n²) arithmetic.
	 *
	 * @param  string $plainText
	 * @param  array  $params     Output of expandKeyV4()
	 * @return string             Nibble-packed ciphertext bytes (before base64)
	 *
	 * @phpstan-param SecureParams $params
	 */
	private static function runEncryptPipelineV4(string $plainText, array $params): string
	{
		$diffused = self::diffuseBytes($plainText, $params);
		$hex      = 'ff' . bin2hex($diffused);
		$binary   = self::hexToBin($hex);

		$queued = self::queueEncrypt($binary, $params['runMax']);
		$queued = self::makePrefixForEncrypt($queued);

		return self::packRleToNibbles($queued);
	}

	/**
	 * V4 decryption pipeline — inverse of runEncryptPipelineV4().
	 *
	 * @param  string $packed  Nibble-packed byte string from runEncryptPipelineV4()
	 * @param  array  $params  Must match params used during encryption
	 * @return string          Decrypted plaintext bytes
	 *
	 * @phpstan-param SecureParams $params
	 */
	private static function runDecryptPipelineV4(string $packed, array $params): string
	{
		$queued   = self::unpackNibblesToRle($packed);
		$queued   = self::makePrefixForDecrypt($queued);
		$binary   = self::queueDecrypt($queued);
		$hex      = self::binToHex($binary);
		$rawBytes = self::fromHex($hex);

		$diffused = substr($rawBytes, 1);

		return self::undiffuseBytes($diffused, $params);
	}

	// ═══════════════════════════════════════════════════════════════════
	// PUBLIC API
	// ═══════════════════════════════════════════════════════════════════

	/**
	 * Encode raw bytes as URL-safe base64 (RFC 4648 §5).
	 *
	 * Replaces '+' → '-' and '/' → '_'. Padding ('=') is preserved
	 * since base64_decode() with strict=true requires it.
	 *
	 * @param  string $data  Raw binary data
	 * @return string        URL-safe base64 string
	 */
	private static function base64urlEncode(string $data): string
	{
		return str_replace(['+', '/'], ['-', '_'], base64_encode($data));
	}

	/**
	 * Decode URL-safe base64 back to raw bytes.
	 *
	 * @param  string $data  URL-safe base64 string
	 * @return string|false  Raw binary data, or false on malformed input
	 */
	private static function base64urlDecode(string $data)
	{
		return base64_decode(str_replace(['-', '_'], ['+', '/'], $data), true);
	}

	/**
	 * Encrypt a plaintext string.
	 *
	 * key = ''  →  Legacy mode  (backward-compatible, no IV, no HMAC)
	 * key != '' →  Secure mode v3  (random IV, verified 8-bit S-box,
	 *              per-round bit-rotation keys, three independent table keystreamss,
	 *              full HMAC-256)
	 *
	 * Secure-mode v3 wire format (before base64url encoding):
	 *   SECURE_MAGIC_V3[2] | IV[16] | attempt[1] | octalLen[4] | octal[N] | HMAC[32]
	 *
	 * The HMAC covers: IV || attempt || octal
	 * This binds all ciphertext fields together and prevents substitution attacks.
	 *
	 * @param  string $plainText  UTF-8 plaintext (arbitrary binary is also accepted)
	 * @param  string $key        Secret key ('' = legacy / no-key mode)
	 * @return string             URL-safe base64 encoded ciphertext
	 */
	public static function encrypt(string $plainText, string $key = ''): string
	{
		// ── Secure mode v4 (compact nibble encoding + AES S-box) ─────
		if ($key !== '') {
			$iv     = random_bytes(self::WIRE_IV_LEN);
			$params = self::expandKeyV4($key, $iv);
			$packed = self::runEncryptPipelineV4($plainText, $params);
			$att    = $params['attempt'];

			$authData = $iv . chr($att) . $packed;
			$hmac     = hash_hmac('sha256', $authData, $params['hmacKey'], true);

			$payload = self::SECURE_MAGIC_V4 . $iv . chr($att) . pack('N', strlen($packed)) . $packed . $hmac;

			return self::base64urlEncode($payload);
		}

		// ── Legacy mode (no IV, no HMAC, backward-compatible) ────────
		$params = self::deriveParams('');
		$octal  = self::runEncryptPipeline($plainText, $params);

		return self::base64urlEncode($octal);
	}

	/**
	 * Extract and verify a secure-mode ciphertext payload.
	 *
	 * Parses the wire format, reproduces the key schedule, and performs
	 * constant-time HMAC verification. Returns null on any failure
	 * (malformed payload, wrong key, tampered data).
	 *
	 * @param  string $payload     Raw decoded payload (after base64 decoding)
	 * @param  int    $payloadLen  Length of $payload in bytes (pre-computed)
	 * @param  string $key         Secret key
	 * @param  int    $hmacLen     Expected HMAC length (16 for v1, 32 for v2)
	 * @return string|null         Decrypted plaintext, or null on authentication failure
	 */
	private static function decryptSecurePayload(string $payload, int $payloadLen, string $key, int $hmacLen): ?string {
		// Minimum length check: magic(2) + IV(16) + attempt(1) + octalLen(4) + octal(≥1) + HMAC
		$minLen = self::WIRE_OCTAL_OFFSET + 1 + $hmacLen;
		if ($payloadLen < $minLen) {
			return null;
		}

		$iv       = substr($payload, self::WIRE_IV_OFFSET, self::WIRE_IV_LEN);
		$att      = ord($payload[self::WIRE_ATT_OFFSET]);
		$octalLen = unpack('N', substr($payload, self::WIRE_OCTAL_LEN_OFFSET, 4))[1];

		// Verify payload is long enough to contain the declared octal data + HMAC
		if ($payloadLen < self::WIRE_OCTAL_OFFSET + $octalLen + $hmacLen) {
			return null;
		}

		$octal = substr($payload, self::WIRE_OCTAL_OFFSET, $octalLen);
		$hmac  = substr($payload, self::WIRE_OCTAL_OFFSET + $octalLen, $hmacLen);

		// Reproduce the exact key schedule used during encryption
		$params = self::expandKey($key, $iv, $att);

		// Compute expected HMAC over the authenticated data (IV + attempt + octal)
		$authData     = $iv . chr($att) . $octal;
		$fullHmac     = hash_hmac('sha256', $authData, $params['hmacKey'], true);
		$expectedHmac = ($hmacLen < 32) ? substr($fullHmac, 0, $hmacLen) : $fullHmac;

		// Constant-time comparison prevents timing side-channel attacks
		if (!hash_equals($hmac, $expectedHmac)) {
			return null;
		}

		return self::runDecryptPipeline($octal, $params);
	}

	/**
	 * Extract and verify a V4 secure-mode ciphertext payload.
	 *
	 * Wire format identical to V2/V3 except the body field holds nibble-packed
	 * bytes rather than an octal string.  Key schedule uses expandKeyV4()
	 * (AES S-box composition + 'BQC-secure-v4' HKDF info tag).
	 *
	 * @param  string $payload     Raw decoded payload (after base64 decoding)
	 * @param  int    $payloadLen  Length of $payload in bytes
	 * @param  string $key         Secret key
	 * @return string|null         Decrypted plaintext, or null on authentication failure
	 */
	private static function decryptSecurePayloadV4(string $payload, int $payloadLen, string $key): ?string
	{
		$hmacLen = self::HMAC_LEN_V2;
		$minLen  = self::WIRE_OCTAL_OFFSET + 1 + $hmacLen;

		if ($payloadLen < $minLen) {
			return null;
		}

		$iv        = substr($payload, self::WIRE_IV_OFFSET, self::WIRE_IV_LEN);
		$att       = ord($payload[self::WIRE_ATT_OFFSET]);
		$packedLen = unpack('N', substr($payload, self::WIRE_OCTAL_LEN_OFFSET, 4))[1];

		if ($payloadLen < self::WIRE_OCTAL_OFFSET + $packedLen + $hmacLen) {
			return null;
		}

		$packed = substr($payload, self::WIRE_OCTAL_OFFSET, $packedLen);
		$hmac   = substr($payload, self::WIRE_OCTAL_OFFSET + $packedLen, $hmacLen);

		$params = self::expandKeyV4($key, $iv, $att);

		$authData     = $iv . chr($att) . $packed;
		$expectedHmac = hash_hmac('sha256', $authData, $params['hmacKey'], true);

		if (!hash_equals($hmac, $expectedHmac)) {
			return null;
		}

		return self::runDecryptPipelineV4($packed, $params);
	}

	/**
	 * Decrypt a ciphertext produced by encrypt().
	 *
	 * Detection order:
	 *   1. SECURE_MAGIC_V4 (0x4255 "BU") — v4: AES S-box + nibble encoding
	 *   2. SECURE_MAGIC_V3 (0x4253 "BS") — v3: per-round keys, full HMAC-256
	 *   3. SECURE_MAGIC_V2 (0x4252 "BR") — v2: full HMAC-256
	 *   4. SECURE_MAGIC    (0x4251 "BQ") — v1: truncated HMAC-128
	 *   5. Legacy (no magic)
	 *
	 * @param  string $cipherText  URL-safe base64 encoded ciphertext
	 * @param  string $key         Secret key (must match the encryption key)
	 * @return string              Decrypted plaintext, or '' on authentication failure
	 */
	public static function decrypt(string $cipherText, string $key = ''): string
	{
		if ($cipherText === '') {
			return '';
		}

		$payload = self::base64urlDecode($cipherText);
		if ($payload === false) {
			return '';
		}

		$payloadLen = strlen($payload);

		// ── Secure mode v4: detect "BU" magic ───────────────────────
		if ($key !== '' && $payloadLen >= self::MIN_PAYLOAD_V4
			&& substr($payload, 0, 2) === self::SECURE_MAGIC_V4
		) {
			return self::decryptSecurePayloadV4($payload, $payloadLen, $key) ?? '';
		}

		// ── Secure mode v3: detect "BS" magic ───────────────────────
		if ($key !== '' && $payloadLen >= self::MIN_PAYLOAD_V3
			&& substr($payload, 0, 2) === self::SECURE_MAGIC_V3
		) {
			return self::decryptSecurePayload($payload, $payloadLen, $key, self::HMAC_LEN_V2) ?? '';
		}

		// ── Secure mode v2: detect "BR" magic ───────────────────────
		if ($key !== '' && $payloadLen >= self::MIN_PAYLOAD_V2
			&& substr($payload, 0, 2) === self::SECURE_MAGIC_V2
		) {
			return self::decryptSecurePayload($payload, $payloadLen, $key, self::HMAC_LEN_V2) ?? '';
		}

		// ── Secure mode v1: detect "BQ" magic (backward compat) ─────
		if ($key !== '' && $payloadLen >= self::MIN_PAYLOAD_V1
			&& substr($payload, 0, 2) === self::SECURE_MAGIC
		) {
			return self::decryptSecurePayload($payload, $payloadLen, $key, self::HMAC_LEN_V1) ?? '';
		}

		// ── Legacy mode (no magic bytes, no authentication) ─────────
		$params = self::deriveParams($key);
		return self::runDecryptPipeline($payload, $params);
	}
}
